term-tsukuyomi","route":"/wiki/terms/tsukuyomi","keywords":["月夜见","ツクヨミ","虚拟空间"]},{"id":"quick-yachiyo-cup","label":"八千代杯","meta":"世界观／音乐词条","target":"term-yachiyo-cup","route":"/wiki/terms/yachiyo-cup","keywords":["ヤチヨカップ","竞赛"]},{"id":"quick-kassen","label":"KASSEN","meta":"世界观／音乐词条","target":"term-kassen","route":"/wiki/terms/kassen","keywords":["对战游戏","合战"]},{"id":"quick-black-onyx","label":"Black onyX","meta":"世界观／音乐词条","target":"term-black-onyx","route":"/wiki/terms/black-onyx","keywords":["职业玩家","帝アキラ"]},{"id":"quick-remember","label":"Remember","meta":"世界观／音乐词条","target":"song-remember","route":"/wiki/terms/remember","keywords":["月见八千代","yuigot"]},{"id":"quick-reply","label":"Reply","meta":"世界观／音乐词条","target":"song-reply","route":"/wiki/terms/reply","keywords":["辉夜","kz","livetune"]},{"id":"quick-taketori","label":"《竹取物语》","meta":"世界观／音乐词条","target":"term-taketori","route":"/wiki/terms/taketori","keywords":["辉夜姬传说","竹中婴儿","月之使者"]}],"spoilerSteps":[["相遇与共同创作","彩叶从发光电线杆中遇见迅速长大的辉夜。两人在现实共同生活，也在月读组成由彩叶写歌、辉夜登台的创作搭档。"],["八千代杯与对决","为了与八千代同台，她们参加八千代杯，并在 KASSEN 活动中与 Black onyX 正面对决。胜负之外，直播让她们获得了真正的关注。"],["回月与《Reply》","辉夜终究被月之使者带走。彩叶没有再次放弃音乐，而是完成《Reply》，让未能当面说完的回应穿过距离。"],["8000 年的时间闭环","辉夜返航时落到约 8000 年前。漫长岁月后，她以月见八千代的虚拟形象建立月读、等待彩叶；八千代正是跨越时间而来的辉夜。"],["十年后的重逢","彩叶选择学习相关技术，并在约十年后为辉夜／八千代打造能够感受现实的身体。实体辉夜、虚拟八千代与彩叶最终同台，完成跨越时间的快乐结局。"]],"musicGroups":[{"id":"all","label":"全部"},{"id":"original","label":"原创／主题"},{"id":"cover","label":"翻唱"},{"id":"remix","label":"重混音"}],"music":[{"id":"song-ex-otogibanashi","title":"Ex-Otogibanashi","type":"主题曲","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"original","note":"作品主题曲，标题呼应“超越童话”。"},{"id":"song-ray","title":"ray 超かぐや姫！Version","type":"片尾曲","creator":"藤原基央／TAKU INOUE 编曲","performer":"辉夜、月见八千代","category":"cover","note":"改编自 BUMP OF CHICKEN《ray》的电影版本。"},{"id":"song-melt","title":"メルト CPK! Remix","type":"特别曲","creator":"ryo (supercell)","performer":"辉夜","category":"remix","note":"《Melt》的 CPK! 重混音。"},{"id":"song-remember","title":"Remember","type":"插入歌","creator":"真崎エリカ／yuigot","performer":"月见八千代","category":"original","note":"关于等待、记忆与时间回声的核心歌曲。"},{"id":"song-starry-sea","title":"星降る海","type":"插入歌","creator":"Aqu3ra","performer":"月见八千代","category":"original","note":"由 Aqu3ra 作词、作曲及编曲。"},{"id":"song-love-myself","title":"私は、わたしの事が好き。","type":"插入歌","creator":"shito、Gom／HoneyWorks","performer":"辉夜","category":"original","note":"突出辉夜的自我肯定与舞台个性。"},{"id":"song-world-is-mine","title":"ワールドイズマイン CPK! Remix","type":"插入歌","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"remix","note":"VOCALOID 经典曲目的 CPK! 重混音。"},{"id":"song-happy-synthesizer","title":"ハッピーシンセサイザ","type":"插入歌","creator":"EasyPop／yuigot 编曲","performer":"辉夜","category":"cover","note":"电影中的翻唱版本。"},{"id":"song-symphony","title":"瞬間、シンフォニー。","type":"插入歌","creator":"40mP","performer":"辉夜","category":"original","note":"由 40mP 作词、作曲及编曲。"},{"id":"song-reply","title":"Reply","type":"插入歌","creator":"真崎エリカ／kz (livetune)","performer":"辉夜","category":"original","note":"与《Remember》构成叙事上的“回应”。"},{"id":"song-onyxxx","title":"OnyXXX","type":"插入歌","creator":"Conisch","performer":"Black onyX","category":"original","note":"帝明、驹泽雷与驹泽乃依演唱的团队形象曲。"},{"id":"song-lonely-universe","title":"ロンリーユニバース","type":"翻唱曲","creator":"Aqu3ra","performer":"月见八千代","category":"cover","note":"月见八千代的官方唱见企划曲。"},{"id":"song-taketori-overnight","title":"竹取オーバーナイトセンセーション","type":"翻唱曲","creator":"Gom／HoneyWorks、MARUMOCHI 编曲","performer":"辉夜","category":"cover","note":"与《竹取物语》母题呼应的官方唱见企划曲。"},{"id":"song-torinoko-city","title":"トリノコシティ","type":"翻唱曲","creator":"40mP","performer":"月见八千代","category":"cover","note":"月见八千代的官方唱见企划曲。"},{"id":"song-dreaming-island","title":"夢をみる島","type":"翻唱曲","creator":"yuigot","performer":"辉夜","category":"cover","note":"辉夜的官方唱见企划曲。"},{"id":"song-tell-your-world","title":"Tell Your World","type":"翻唱曲","creator":"kz (livetune)","performer":"月见八千代","category":"cover","note":"月见八千代的官方唱见企划曲。"}],"staff":[["导演","山下清悟"],["编剧","夏生さえり、山下清悟"],["月读角色设计","へちま"],["现实角色设计","永江彰浩"],["Live 演出","中山直哉"],["美术监督","宍户太一"],["色彩设计","广濑泉"],["月读概念设计","東みずたまり、フジモトゴールド"],["现实概念设计","刈谷仁美"],["CG 监督","町田政弥"],["CG 背景","草间彻也（QUUNPLANT）"],["剪辑","木南凉太"],["摄影监督","千叶大辅"],["音响监督","三好庆一郎"],["配乐","Conisch"],["企划、制作","山本幸治"],["出品","Colorido・TWIN ENGINE PARTNERS"],["动画制作","STUDIO COLORIDO、STUDIO CHROMATO"]],"cast":[["辉夜","夏吉优子"],["酒寄彩叶","永濑安奈"],["月见八千代","早见沙织"],["帝明／酒寄朝日","入野自由"],["驹泽雷","内田雄马"],["驹泽乃依","松冈祯丞"],["绫䌷芦花","青山吉能"],["谏山真实","小原好美"],["FUSHI","钉宫理惠"],["忠犬宅公","菲鲁兹·蓝"],["乙事照琴","花江夏树"],["犬DOGE","庄司更纱"],["酒寄红叶","坂本真绫"],["酒寄朝久","铃村健一"],["班主任","小林亲弘"],["音乐老师","宫泽清子"]],"boxOfficeMilestones":[{"day":"上映 26 天","gross":"突破 10 亿日元"},{"day":"上映 44 天","gross":"达到 16.8 亿日元"},{"day":"上映 59 天","gross":"达到 20 亿日元"},{"day":"上映 86 天","gross":"达到 25 亿日元"}],"derivativeWorks":[{"type":"漫画版","title":"《超时空辉夜姬！》漫画版","image":"/assets/images/wiki/content/source-053.webp","imageAlt":"《超时空辉夜姬！》漫画版第 1 卷封面","credits":"作画：米田タロウ","publisher":"KADOKAWA／Kadokawa Comics A","release":"第 1 卷：2026-02-10","isbn":"978-4-04-811757-9","detail":"于 Comic Comp 连载，将电影故事改编为漫画叙事。"},{"type":"小说版","title":"《超时空辉夜姬！》小说版","image":"/assets/images/wiki/content/source-055.webp","imageAlt":"《超时空辉夜姬！》小说版封面","credits":"著：桐山なると／插画：うらたあさお","publisher":"KADOKAWA／Fami通文库","release":"2026-01-30","isbn":"978-4-04-738734-8","detail":"以文字形式重新讲述电影中的相遇、创作与离别。"},{"type":"公式指南书","title":"《超かぐや姫！ 公式ガイドブック ハッピーエンドのその先へ！》","image":"/assets/images/wiki/content/source-056.webp","imageAlt":"《超时空辉夜姬！》公式指南书封面","credits":"官方设定与制作资料集","publisher":"KADOKAWA","release":"2026-01-30","isbn":"978-4-04-117055-7","detail":"收录角色设定、制作资料与 Happy End 之后的补充内容。"}],"references":[{"id":"ref-official","label":"《超かぐや姫！》作品官方网站","url":"https://www.cho-kaguyahime.com/","scope":"故事、角色、制作人员与视觉资料"},{"id":"ref-music","label":"作品官方网站 Music","url":"https://www.cho-kaguyahime.com/music/","scope":"歌曲、创作者与官方 MV 入口"},{"id":"ref-tudum","label":"Netflix Tudum 专题","url":"https://www.netflix.com/tudum/articles/cosmic-princess-kaguya-release-date-news","scope":"上线日期、核心设定与主角配音"},{"id":"ref-netflix","label":"Netflix 中文作品页","url":"https://www.netflix.com/sg-zh/title/81756595","scope":"平台简介与地区中文片名"},{"id":"ref-kadokawa","label":"KADOKAWA 官方商品页","url":"https://www.kadokawa.co.jp/product/322510000049/","scope":"官方导览书与出版信息"},{"id":"ref-guideline","label":"作品官方网站：二次创作指南","url":"https://www.cho-kaguyahime.com/special/detail.html?id=1024","scope":"官方素材使用边界；公开素材不等于自由许可"},{"id":"ref-moegirl","label":"萌娘百科：《超时空辉夜姬！》源条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81","scope":"上映、主创、配音、曲目、票房与衍生作品的参考目录"},{"id":"ref-wikipedia","label":"中文维基百科条目","url":"https://zh.wikipedia.org/wiki/%E8%B6%85%E6%99%82%E7%A9%BA%E8%BC%9D%E8%80%80%E5%A7%AC%EF%BC%81","scope":"片长、发行与曲目交叉核对；非唯一来源"},{"id":"ref-ciatr","label":"ciatr 剧情解说","url":"https://ciatr.jp/topics/335940","scope":"结局时间线的二手交叉核对；推测不作为官方设定"}],"navigationGroups":[{"title":"角色","links":[{"label":"辉夜","target":"entry-kaguya","route":"/wiki/characters/kaguya"},{"label":"酒寄彩叶","target":"entry-iroha","route":"/wiki/characters/iroha"},{"label":"月见八千代","target":"entry-yachiyo","route":"/wiki/characters/yachiyo"},{"label":"帝アキラ","target":"entry-akira","route":"/wiki/characters/akira"},{"label":"驹泽雷","target":"entry-rai","route":"/wiki/characters/rai"},{"label":"驹泽乃依","target":"entry-noi","route":"/wiki/characters/noi"}]},{"title":"月读档案","links":[{"label":"月读／TSUKUYOMI","target":"term-tsukuyomi","route":"/wiki/terms/tsukuyomi"},{"label":"八千代杯","target":"term-yachiyo-cup","route":"/wiki/terms/yachiyo-cup"},{"label":"KASSEN","target":"term-kassen","route":"/wiki/terms/kassen"},{"label":"Black onyX","target":"term-black-onyx","route":"/wiki/terms/black-onyx"}]},{"title":"音乐","links":[{"label":"Ex-Otogibanashi","target":"song-ex-otogibanashi"},{"label":"ray 超かぐや姫！Version","target":"song-ray"},{"label":"メルト CPK! Remix","target":"song-melt"},{"label":"Remember","target":"song-remember"},{"label":"星降る海","target":"song-starry-sea"},{"label":"私は、わたしの事が好き。","target":"song-love-myself"}]}],"entries":[{"kind":"character","kindLabel":"角色词条","slug":"kaguya","title":"辉夜","original":"かぐや","headline":"从月球闯入东京日常，以歌声、行动力和跨越时间的约定追寻 Happy End 的少女。","summary":"从月球来到地球的神秘少女。她外向、自由，对地球上一切有趣之物充满好奇；在彩叶的帮助下走进月读，成为负责演唱与直播的表演者。","aliases":["辉夜姬","かぐや","月球少女","外星人"],"tags":["月球少女","歌手","主播"],"facts":[["年龄","初登场约 10 个月（外观快速成长）"],["生日","7 月 12 日"],["声优","夏吉优子"],["出身","月球"],["身份","月人公主／主播／歌手"],["活动组合","辉夜×彩P"],["活动范围","现实东京、虚拟空间“月读”"],["能力","快速成长、改变外观、料理与高速学习"],["喜好","甜食、零食与有趣的新鲜事物"],["代表歌曲","Reply、瞬間、シンフォニー。"]],"sections":[["人物简介",["辉夜是从月球来到地球的少女。她搭乘的飞船意外落在酒寄彩叶居所附近，最初以婴儿形态出现，又在短短数日内迅速成长。彩叶根据《竹取物语》为她取名“辉夜”，两人的共同生活也由此开始。","她不喜欢月球上重复而乏味的生活，把地球视为寻找乐趣和自由的新舞台。接触电脑后，她以惊人的速度掌握语言、互联网和现代生活知识，并很快对虚拟空间“月读”产生兴趣。","辉夜在现实中保留金色长发和宽松黑色上衣的轻快形象；进入月读后，则使用带兔耳、和服轮廓和月牙装饰的“月夜见”形象。页面顶部可以在两种形态之间切换。"]],["性格、能力与爱好",["辉夜开朗、调皮、爱撒娇，而且几乎没有面对陌生环境的拘谨感。她想到什么便立刻尝试，常常先行动再考虑后果；这种冒失既制造了许多麻烦，也是她不断突破困境的动力。","月人的身体让她拥有远超常人的成长速度和适应能力。她能够改变发色、肤色等外观特征，运动能力也十分突出；配合高速学习，她可以在很短时间内掌握设备、网络文化和直播流程。","她喜欢甜食、零食和热闹的活动，同时有出色的料理天赋。初次认真下厨便做出令彩叶印象深刻的料理，但她购买高级食材和直播设备时缺少金钱观念，也经常让生活拮据的彩叶措手不及。"]],["与酒寄彩叶",["彩叶起初只是无法放任来历不明的孩子，随后逐渐承担起监护人与家人的角色。辉夜从彩叶的哼唱中获得最早的安全感，而彩叶也因为辉夜毫无保留的需要与信任，第一次拥有了能够共同生活的“家”。","辉夜发现彩叶隐藏起来的音乐才能后，主动邀请她成为搭档。彩叶以“彩P”的身份负责作曲、编曲、设备和运营，辉夜则承担演唱、直播与镜头前的表演，两人组成“辉夜×彩P”。","两人的关系贯穿照顾、创作和相互拯救。辉夜把彩叶带回音乐之中，彩叶则不断拒绝接受命运安排的离别；她们共同追求的 Happy End，不是被动等待的结局，而是需要亲手创造的未来。"]],["组合活动与八千代杯",["辉夜第一次进入月读便遇见管理员兼顶级主播月见八千代，并观看了她的演唱会。八千代宣布“八千代杯”后，辉夜为了赢得与偶像同台合唱的机会，当场决定参加主播涨粉竞赛。","她最初的直播缺乏规划，甚至在出道视频中暴露现实身份；彩叶加入后，两人把即兴企划、音乐创作和精细运营结合起来，粉丝增长逐渐加速。辉夜还向芦花和真实请教直播经验，让原本私人的日常发展成完整的舞台活动。","面对顶流组合“黑玛瑙”，辉夜和彩叶接受《合战》3V3挑战。虽然比赛由黑玛瑙获胜，但辉夜×彩P凭借活动期间积累的人气，以微弱优势夺得八千代杯冠军，并取得与八千代举办联动演唱会的资格。"]],["角色意象与生活细节",["松饼是辉夜和彩叶共同生活的重要记忆。彩叶最初用面粉和水做出的简陋食物并不好吃，却成为辉夜在漫长岁月中反复怀念的味道；它代表的并非料理本身，而是两人刚刚成为家人的时刻。","旧居漱口杯中牙刷数量的变化记录了辉夜进入彩叶生活的过程：从一支变成两支，意味着两人的物品与日常逐渐交叠；在八千代复原的记忆房间里，它又回到一支，暗示她对过去既眷恋又不敢靠近。","彩叶的黑色旧 T 恤也贯穿辉夜的不同成长阶段。同一件衣服在不同年龄外观以及八千代身上呈现出不同效果，将婴儿般的依赖、少女时期的亲密和八千年后的记忆连接在一起。"]],["歌曲与核心主题",["《Reply》由彩叶为辉夜创作，其旋律与八千代的《Remember》彼此呼应。两首歌分别承载“回应”与“记忆”，歌声最终成为穿越月球、现实与时间的通讯方式。","辉夜的故事重新解释了《竹取物语》的离别结局：她知道自己可能被月人带走，却始终相信结局可以被重新书写。角色的行动、直播和歌声都围绕同一个愿望展开——不把失去当作终点，而是把所有重要的人一起带向幸福。"]]],"spoiler":["辉夜与彩叶赢得八千代杯后搬入新居，并迎来与八千代的联动演唱会。演出期间出现月人发出的异常讯号，辉夜随后向彩叶坦白：她是逃离月球的公主，必须在 2030 年 9 月 12 日的满月之夜返回。","辉夜发布隐退声明，并把毕业演唱会作为告别舞台。彩叶联合八千代、黑玛瑙、芦花和真实尝试阻止月人，但最终仍未能留下她；现实中的辉夜在与彩叶告别后消失，月读中的形象也如《竹取物语》中的辉夜姬般升向月面。","彩叶拒绝把离别包装成一个勉强的好结局，完成新歌并借辉夜留下的手环向月球传递歌声。她发现《Reply》与《Remember》拥有相同的旋律，也因此意识到失踪的八千代与辉夜存在直接联系。","返回月球后的辉夜为了再次见到彩叶，制造了能够穿越时间的飞船，却因事故落入约八千年前的地球。她只能依靠 FUSHI 与外界交流，并在漫长历史中等待互联网出现，最终利用月人科技建立虚拟空间“月读”，以“月见八千代”的身份继续守望彩叶。","八千代认为经历八千年后的自己已经不能再作为昔日的辉夜面对彩叶，甚至想删除对方的悲伤记忆。彩叶通过 FUSHI 接收她漫长岁月中的记忆，理解了欢笑、战争、孤独与等待怎样让“辉夜”逐渐成为“八千代”，并明确表示仍然希望与她在一起。","由于八千代在月读中无法感受体温和味觉，彩叶转向相关科学领域，用十年时间推进感知系统与合成人躯体研究。最终，拥有熟悉金发与面容的新身体苏醒，辉夜／八千代获得重新进入现实生活的机会，作品所追求的 Happy End 至此真正完成。"],"relatedCharacters":["iroha","yachiyo","fushi","doge"],"relatedTerms":["tsukuyomi","yachiyo-cup","reply","taketori"],"image":"/assets/images/wiki/entries/characters/kaguya-reality.webp","imageLayout":{"ratio":"1200 / 1620","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的萌娘百科清晰角色图（现实形象）"},"imageAlt":"辉夜现实形象透明立绘","imageVariants":[{"id":"reality","label":"现实","image":"/assets/images/wiki/entries/characters/kaguya-reality.webp","imageAlt":"辉夜现实形象透明立绘","imageLayout":{"ratio":"1200 / 1620","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的萌娘百科清晰角色图（现实形象）"}},{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/kaguya-tsukuyomi.webp","imageAlt":"辉夜月夜见形象透明立绘","imageLayout":{"ratio":"1200 / 1620","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的萌娘百科清晰角色图（月夜见形象）"}}],"imageTarget":"assets/images/wiki/entries/characters/kaguya-reality.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"kaguya","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E8%BE%89%E5%A4%9C(%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81)","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科：辉夜（本页资料参考）","url":"https://zh.moegirl.org.cn/%E8%BE%89%E5%A4%9C(%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81)"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"character","slug":"yachiyo","label":"月见八千代"},{"kind":"character","slug":"fushi","label":"FUSHI"},{"kind":"character","slug":"doge","label":"犬DOGE"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"},{"kind":"term","slug":"yachiyo-cup","label":"八千代杯"},{"kind":"term","slug":"reply","label":"Reply"},{"kind":"term","slug":"taketori","label":"《竹取物语》"}],"songs":[{"id":"song-ex-otogibanashi","title":"Ex-Otogibanashi","type":"主题曲","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"original","note":"作品主题曲，标题呼应“超越童话”。"},{"id":"song-ray","title":"ray 超かぐや姫！Version","type":"片尾曲","creator":"藤原基央／TAKU INOUE 编曲","performer":"辉夜、月见八千代","category":"cover","note":"改编自 BUMP OF CHICKEN《ray》的电影版本。"},{"id":"song-melt","title":"メルト CPK! Remix","type":"特别曲","creator":"ryo (supercell)","performer":"辉夜","category":"remix","note":"《Melt》的 CPK! 重混音。"},{"id":"song-love-myself","title":"私は、わたしの事が好き。","type":"插入歌","creator":"shito、Gom／HoneyWorks","performer":"辉夜","category":"original","note":"突出辉夜的自我肯定与舞台个性。"},{"id":"song-world-is-mine","title":"ワールドイズマイン CPK! Remix","type":"插入歌","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"remix","note":"VOCALOID 经典曲目的 CPK! 重混音。"},{"id":"song-happy-synthesizer","title":"ハッピーシンセサイザ","type":"插入歌","creator":"EasyPop／yuigot 编曲","performer":"辉夜","category":"cover","note":"电影中的翻唱版本。"}],"source":{"profileRows":[{"label":"地区译名","valueHtml":"简体中文：辉夜<br>繁体中文：輝耀","group":false},{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"かぐや","group":false},{"label":"别号","valueHtml":"辉夜姬、外星人、<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">八千代</span>","group":false},{"label":"多种发色","valueHtml":"<span class=\"wiki-source-traits\">变发色、可自由变色</span>，作品中常为金色","group":false},{"label":"瞳色","valueHtml":"金","group":false},{"label":"年龄","valueHtml":"10个月<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">8000岁</span>","group":false},{"label":"生日","valueHtml":"7月12日<span class=\"wiki-source-category\">分类:7月12日</span> <span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">月球人抵达地球之日</span>","group":false},{"label":"声优","valueHtml":"夏吉优子","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">元气、撒娇、阳角、自来熟、网络主播、网络偶像、歌手、料理达人、长发、姬发式、手环、齐刘海、甜食控、女儿、del、百合、黑幕</span><br>月读：<span class=\"wiki-source-traits\">超长发、尾扎长发、和服、兔耳、短袜、运动鞋、露肩装、露腋、露脐装</span><sup class=\"wiki-source-reference\">注：腰部的月牙图案不是印花，而是镂空</sup>","group":false},{"label":"出身地区","valueHtml":"月球","group":false},{"label":"活动范围","valueHtml":"月球→<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">日本东京</a>","group":false},{"label":"个人状态","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">继续轮回→与彩叶幸福地生活在一起的Happy End</span>","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"好<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">姬</span>友：<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">虚拟世界化身、8000年后的自己：<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a></span>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>好，决定了！要自己创造Happy End，而且要把彩叶也一起带到Happy End，一起！（一休尼！）</strong></big></blockquote>\n<p><strong>辉夜</strong>（<strong>かぐや</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>初登场时的形象是“来自月亮的神秘少女”<del>，但严谨地说，应该是来自月亮的神秘婴儿</del>。</p>\n<p>开朗调皮、喜欢撒娇。自称来到地球是为了寻找乐趣，并因此在虚拟空间「月夜见」内开展主播活动。</p>\n<p>学习能力强得不可思议，与之相符的是似乎永远用不完的行动力，会仅凭一个念头而立刻付诸行动。</p>\n<p>料理能力高超，初次上手的料理便让能彩叶流下“幸福的眼泪”<del>，虽说食材的成本也价值不菲</del>。</p>\n<p>抱着一切都要上手试试的想法，无忧无虑地在地球享受着与彩叶在一起的愉快时光。然而……</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>话说，那是在一个既不是太古、也不是超未来……咳，总之是在一个与现代相差无几、只是相较向前迈进了一小步的世界，发生了这么一件有趣的故事：</p>\n<p>某天，或许是对重复又无聊的社畜生活感到厌倦，一位来自月球的公主突然决定放下工作，抱着“可能是想要逃到更有趣的地方”的想法，乘上了独自前往地球的竹笋飞船。</p>\n<p>或许是出自什么机缘巧合<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">未必</span>，公主的飞船误打误撞地抵达我们的主人公<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>所住的公寓门前……的电线杆中，七彩的光芒随后化为了一个美丽又可爱的小婴儿。虽然内心十分甚至九分地纠结，但心地善良的彩叶还是战战兢兢地将婴儿带回家里；并在使劲浑身解数之后，总算通过哼唱<a class=\"wiki-source-link\" href=\"/wiki/terms/remember\">某首熟悉的旋律</a>，让哭闹不止的婴儿安静了下来。</p>\n<p>应该说不愧是来自月球的孩子，这个小婴儿在接下来的几天里以肉眼可见的速度迅速成长；虽说她的到来让正值高二年级、独自一人过活的彩叶压力山大，但彩叶还是下意识地承担起了监护人的职责。</p>\n<p>某夜，小公主嚷嚷着肚饿，吵醒了彩叶；彩叶迷迷糊糊地应声，却在下一刻发现了令她瞠目结舌的事实：这个奇怪的小婴儿已经蜕变为了有着十岁孩童外观的美丽女孩，而面对女孩天真无邪的恳求，彩叶不论如何也无法狠下心来。</p>\n<p>在费了好一番口舌后，彩叶总算从狼吞虎咽地吃光了两人份晚饭的女孩口中得知了一些信息——眼前的女孩确实是一个外星人，她通过自己的个人电脑迅速学习了有关地球与互联网的知识，并且与古老童话《竹取物语》中的辉夜姬有着若干异曲同工之处。虽然女孩对《竹取物语》的原版结局非常不满，大剌剌地说着什么“要创造一个Happy End，而且要把彩叶也一起带去”，但彩叶实在是捱不住困意了。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-004.webp\" alt=\"辉夜姬-颜艺1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>令人感慨的是，辉夜吃到的这第一口正儿八经的松饼，还是芦花女士请的……</figcaption>\n  </figure>\n<p>次日，彩叶苏醒时发现少女不见，误以为这几天的经历是一场梦，随即惨遭打脸；无奈，她为又长大了一些的少女准备了粗劣的穷鬼版松饼，并在警告对方不要惹事后出门上学。然而，令她大跌眼镜的是，少女不仅尾随她跑出家门，一路追到她接受芦花和真实款待的咖啡厅，还鲸吞了本属于她的美味松饼谢礼；为了掩人耳目，她只得谎称少女是自己的表妹，还根据早些时候的交流为其命名为“辉夜”，并带着辉夜仓皇逃离现场。然而，这不是辉夜捅的唯一一个篓子——在彩叶的追问下，她发现辉夜用自己的积蓄购买了智能隐形眼镜，还准备了成本惊人而美味至极的料理。吃人嘴短加上没法退款，大破费的彩叶只得勉强答应辉夜，准许其在自己身边暂住，并引荐辉夜首次登入了虚拟空间“月夜见”（下文称“月读空间”）。</p>\n<p>在这个世界里，月读空间作为一个<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">疑似仅在本国便</span>拥有上亿用户的超级综合体，与现实深度融合，是最流行的时代产物。这个虚拟空间有着一位名叫<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a>的神秘AI，作为其管理员兼新手引导兼虚拟艺人；而彩叶作为八千代的狂热粉丝；在生活中高度依赖八千代提供的精神价值<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，包括但不限于提神、镇定、健胃消食等</span>，甚至将其视为自己的唯一寄托。</p>\n<p>彩叶所言不虚，初次登入月读空间的辉夜果然在新手引导环节遭遇了美丽而神秘的八千代，在对方的悉心指导与殷切注视下，辉夜兴高采烈地越过鸟居状的传送门<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然后狠狠地摔了个大马趴</span>。面对候在门口的彩叶，辉夜愉快地向对方展示了经过自己改造、同样得以进入月读空间的电子宠物“狗狗DOGE”，还就这个虚拟世界的基础概念进行了一番交流；两人随即前往八千代的迷你演唱会，准备欣赏今夜的演出。</p>\n<p>在观众们热切的倒计时中，万众瞩目的八千代准时出现在高高的鸟居舞台之上，她愉快地向着各位莅临的神明大人们问好，并献上了一曲幸福洋溢的《<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%98%9F%E9%99%8D%E3%82%8B%E6%B5%B7\" target=\"_blank\" rel=\"noopener noreferrer\">星降る海</a>》。接着，八千代向观众们公布了自己即将举办的活动“八千代杯”——这是一场比拼主播涨粉数量的活动，最终的冠军将会获得与八千代一起办联动演唱会的机会。由于八千代此前从来没有进行过合唱演唱会，这个消息对于彩叶这种粉丝头子来说无异是一枚重磅炸弹；但辉夜却对此表现得兴致勃勃，并在随后赶到、咄咄逼人的顶流组合“黑玛瑙”的刺激下，向着鸟居舞台上的八千代大声发出了必胜的宣言。</p>\n<p>面对初生牛犊不怕虎的辉夜，八千代不由得感慨对方的可爱，而彩叶则是迅速控制住辉夜、羞耻得恨不得钻到地缝里去。演唱会刚一结束，辉夜便迫不及待地搜索起成为主播的相关资料，还购入了一大堆乱七八糟的直播道具；她甚至做了一个难以恭维、堪称“经典”的出道视频，首次配信就暴露了<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%AD%E4%B9%8B%E4%BA%BA\" target=\"_blank\" rel=\"noopener noreferrer\">中之人</a>的面目。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-038.webp\" alt=\"辉夜姬-于是她就这样闯进了她的世界\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>一边是满满的乱来、而另一边则是枯燥乏味的现实，她就这样闯入了她的世界</figcaption>\n  </figure>\n<p>虽说能吐槽的地方多得数不完，但彩叶还是对这个出道视频里魔音贯耳的“BGM”表现出好奇，她这才发现辉夜偷偷翻出了自己的键盘。面对辉夜的恭维与期待，彩叶感到内心深处仿佛有什么东西随着音乐从指尖流淌而出，这种被她封存了许久的感觉，连同辉夜笨拙而热切的恳求，以及与八千代同台演出的诱惑，使她最终答应了辉夜的邀请。两人就此组成“辉夜x彩P”组合正式出道，开始了属于她们的王道征途。</p>\n<p>想到什么就拍什么、觉得什么有趣就做什么；辉夜的信条中似乎不存在“做不到”，而对于这些想做的事情，辉夜几乎毫不犹豫。她超强的行动力结合彩叶顶尖的运营能力，使得两人的涨粉数蒸蒸日上；由于彩叶需要兼顾学业，辉夜还拉上了同为人气主播的芦花与真实，向两人认真取经；她甚至还口无遮拦地效仿《竹取物语》的辉夜姬来了个比武招亲，而这些求婚者则无一例外地倒在了护犊心切的彩P手下。</p>\n<p>某日，过劳的彩叶被通宵直播的辉夜吵醒，终于在次日坚持不住而倒下；辉夜为了让彩叶好好休息，尽可能地安排好了一切事宜，还认为彩叶病倒是自己带来的压力所致，担心彩叶随时可能死去而大哭不止。对此，彩叶向辉夜讲述了自己与母亲的纠葛；辉夜为母女间的关系表现得十分动容，却也尊重了彩叶的想法。</p>\n<p>纵使两人使劲浑身解数，“辉夜x彩P”的涨粉速度距离高居榜首的“黑玛瑙”仍有巨大差距。就在辉夜对此感到苦恼的时候，“黑玛瑙”的队长帝明主动向两人发来了《合战》的3V3挑战书——其实，帝明的真实身份正是彩叶的哥哥朝日，他很早就注意到了妹妹与辉夜的活跃，虽然在嘴上叫嚣着要辉夜输给自己后嫁给自己为妻，实际上是想凭借自己超级大物的身份拉她们一把。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-045.webp\" alt=\"辉夜姬-“那是我的！”\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「喂，那是我的！」</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-046.webp\" alt=\"辉夜姬-“再不走的话……就回不去了呀”\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「再不回家不行了哦……不然，就回不去了。」</figcaption>\n  </figure>\n<p>比赛当日，被两人组拉来凑人头的真实因近距离目睹偶像，情绪过于激动而无法继续比赛；此时八千代突然乱入，作为替补队员加入了彩叶与辉夜的队伍<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然而此时芦花就在看台上，八千代的小心思昭然若揭</span>。在与“黑玛瑙”进行鏖战期间，彩叶被迫脱下自己用于掩盖身份的狐狸皮套，公开了与帝明的兄妹关系，并在最后理解了哥哥的良苦用心，解除了兄妹间的误会。</p>\n<p>由于实力差距实在不小，“黑玛瑙”精彩地赢下了《合战》3V3挑战，但彩叶与辉夜却凭借种种加成，以微弱优势获得了“八千代杯”的胜利。随后，彩叶委托哥哥朝日作为担保人，兑现与辉夜“搬进新居”的约定，姐妹俩搬进了环境更好的顶层公寓套间，还从揣面团开始、制作了一餐意面作为庆贺。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-047.webp\" alt=\"辉夜姬-“……最喜欢你了。”\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>“……即使我紧紧抱住自己，紧到皮肤都要发出悲鸣，那份温暖，还是慢慢地消失了。”</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-048.webp\" alt=\"辉夜姬-“……天人拉了这车子，辉夜姬便升天去了”\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>“……有一百个天人拉了这车子，辉夜姬便升天去了。”——《竹取物语》</figcaption>\n  </figure>\n<p>在与八千代联动演出的前夜，彩叶紧张得睡不着觉，而辉夜则是一如既往地钻进她的被窝，闻着辉夜的味道，彩叶难得地睡了个好觉。次日，两人在准备室与翩然降临的八千代相遇，趁着登台前的时机，彩叶询问八千代是否还会再演唱出道曲《Remember》，八千代则是含糊地表示“这首歌已经传达到了”，没有留给彩叶追问的机会。</p>\n<p>三人的联动演唱会取得了空前成功，辉夜甚至还借着绝佳的气氛向彩叶直球告白求婚，搞得彩叶脸红心跳；然而，三人所在的舞台却在这时遭遇奇怪人形的围攻，辉夜在接触到人形的瞬间失去知觉；虽然八千代迅速驱逐了人形，并表示会对此进行追查，但八千代和辉夜在意外发生前后的古怪表现却让彩叶生起疑心。</p>\n<p>相比起八千代的语焉不详，辉夜的故作镇定令彩叶更加不安。此时芦花与真实恰好发来助攻，在两人的鼓励下，彩叶破天荒地主动邀请辉夜去看烟火大会，收到了辉夜狂喜乱舞的回复。面对漫天烟花，辉夜认真询问了彩叶对于妈妈的看法，并向彩叶吐露了自己的真实身份——她确实是不甘无聊、逃出月球的月人公主，此前的插曲正是月人发出的引渡讯号，而她即将在下个月圆之夜离开——亦即公元2030年9月12日，农历八月十五，中秋节。面对即将告别的事实，辉夜仿佛在一瞬间变得成熟，她强打精神，努力地说着鼓励自己和安慰彩叶的话；而彩叶则是握住了辉夜那纤瘦的手腕，她越是想要尊重辉夜的心意，就越感到心如刀绞。</p>\n<p>返回住所后，辉夜立刻发布了隐退声明与毕业演唱会预告，而彩叶则将此前未能与爸爸一起完成的旧作找出，要为辉夜创作临别前的新歌。趁着辉夜休息的当口，彩叶找到了八千代和好朋友们，向他们告知了有关辉夜的真实身份，并计划在辉夜的毕业演唱会上迎击月人，试图挽留辉夜；好友们虽然对于这一事实感到有些意外，却一口答应下来。</p>\n<p>毕业演唱会的日子很快到来。在演出开始前，辉夜将自己始终佩戴的奇特手环托付给了彩叶，作为从彩叶处收到自己名字的答礼。在演唱会开始前，辉夜私下询问了八千代，“如果自己是八千代的话，是否能将彩叶迷得更彻底”，得到了否定的答复<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">；然而，彩叶在片刻后同样私下询问八千代，“如果自己是八千代的话，辉夜会和自己说不想回去吗”，却收获了对方的惊讶，以及“原来你们是两情相悦啊”的奇怪答复</span>。</p>\n<p>演唱会随即开始，伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；彩叶在哥哥等人的支持下抵达了辉夜的舞台前，却仍然无法阻止月人带走辉夜。最终，月读空间中的辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝，而现实中的辉夜则紧紧地拥抱了彩叶，向她进行最后的告白，随即悄然消失。</p>\n<p>彩叶强打精神，对众人平静地表达感谢，然后登出了月读空间；她紧接着收到了辉夜的转账消息，也算是兑现了自己起初向流星许下的愿望。然而，这笔钱已经不重要了，彩叶失魂落魄地走过房间的每一处角落，试图寻回与辉夜曾经度过的时光。</p>\n<p>就这样，彩叶茶饭不思地度过了数日，终于恍然大悟、走出阴影，决定重启自己的人生，而与辉夜度过的经历则将成为一场美好的梦，激励她翻开新的篇章。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>……这样的结局也好意思叫“Happy End”吗？！别开玩笑了！</summary><div><p>倘若故事到此为止，那么这大概也就是一个拙劣的现代版竹取物语，而你彩叶姐是要带给所有人Happy End的超人，怎么可能会容许这种Bad End的发生！</p>\n<p>伴随着“怎么可能就这样结束啊啊啊！”的怒吼，彩叶推翻了自己为了虚假的“可喜可贺”所做的努力，她推辞了一切社交和学习计划，然后接通了来自妈妈的电话。在与妈妈爆发一番前所未有的争吵后，妈妈最终拐着弯儿表达了对彩叶的牵挂和理解，而终于抛下一切的彩叶也总算得以倾注全部时间和精力，在接下来的几天里完成了一首新的歌曲。</p>\n<p>带着煎熬、期待、对爸爸的追念以及对辉夜的眷恋，彩叶捧着辉夜留给自己的手环，向着月亮清唱出了这首刚刚完成的歌曲；思念的力量使得歌声跨越时空，成功传递给了月亮彼端的辉夜，而彩叶却在此时惊讶地发现，另有一个人的声音加入了合唱。</p>\n<p>宛如流星天启一般，彩叶忽然顿悟——她此前为辉夜所作、名为《Reply》的歌曲，有着一段与八千代的出道曲《Remember》相同的旋律；而刚刚加入合唱的人，正是她一直仰慕的八千代。</p>\n<p>自辉夜的演唱会结束以后，八千代也失踪了；不止如此，早在演唱会开始之前，八千代就仿佛人间蒸发、完全没有对月人进行任何干涉。面对重重谜团，彩叶在月读空间四处寻找，随后遭遇了八千代的奇特宠物——海兔FUSHI。在FUSHI的引导下，彩叶于现实中追索到了八千代的物理坐标——一座藏在某公寓楼当中的机房，机房的正中是一座水箱，其中漂浮着一颗竹笋般的奇特存在；彩叶从这里登入月读空间，发现自己出现在一处无名高塔的顶端，而面前背对着自己、长发垂地的少女，正是她苦苦追寻的八千代。</p>\n<p>面对彩叶“辉夜就是八千代吗”的疑问，八千代翩然而起，向彩叶讲述了自己的由来：辉夜在回到月球后，因听到彩叶的歌声而爆肝完成工作；尽管如此，这时的彩叶也已经垂垂老矣，因此辉夜便制造出能够穿越时空的竹笋飞船，准备返回彩叶年轻时的时代；然而，飞船在飞行途中不慎撞击陨石，误打误撞地返回了八千年前的地球，残存的能量只能塑造海兔FUSHI的身体，因此辉夜便通过FUSHI与外界交流；时光流转，人类进入互联网时代，辉夜终于等到机会，基于互联网和月人科技制造了“月读空间”，由此成为了八千代。</p>\n<p>话虽如此，面对八千代“这可没法用皆大欢喜，可喜可贺来干脆地收尾啊”的自嘲，彩叶不论如何也无法理解；她忍不住询问八千代为何能够一直笑着，却发现对方的颤抖逐渐从指尖蔓延至全身——八千代并不是一直笑着，只是漫长的生命令她无力垂泪；她没能兑现当初的诺言，她“搞砸了”，可她仍然以一副无比悲伤的表情，在心爱的彩叶面前强颜欢笑着。</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-003.webp\" alt=\"辉夜姬-……只是在强颜欢笑2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>那个耀眼的辉夜姬……</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-002.webp\" alt=\"辉夜姬-……只是在强颜欢笑\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>……现在已经是个老奶奶了。</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p>colspan=&quot;2&quot;</p>\n<p><em>「那个耀眼的辉夜姬……现在已经是个老奶奶了。」</em></p>\n<p>对于八千代、亦即经历了八千年岁月的辉夜来说，她自认为自己无法再以“辉夜”的身份与彩叶相处，而情愿以“八千代”的身份默默守护彩叶，甚至愿意为彩叶清除这段令人悲伤的记忆，而这引发了彩叶的强烈愤慨。彩叶执拗地要求八千代将过去的经历分享给自己<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，并在熬老太比赛中取得了第一名的好成绩</span>，而八千代则对此感到欣慰；她向彩叶分享了自己从绳纹时代到江户时代的种种愉快见闻，直至抵达系统运行时长上限，不得不强制休息。</p>\n<p>八千代是休息了，但是她的故事并没有讲完；彩叶便转向八千代的小伙伴FUSHI，要求其将八千代的记忆完整地分享给自己。FUSHI的前身正是辉夜曾经制作的电子宠物“狗狗DOGE”，它同样见证了辉夜所经历的八千年，并为彩叶的觉悟所感动。在彩叶的恳求下，FUSHI在极短时间内将漫长岁月的记忆尽数输入彩叶的意识，而这一次，彩叶遭遇了宛如数百倍无量空处的数据轰炸；她以辉夜/八千代的第一视角，目睹了爱人在漫长岁月里所经历的一切——欢笑、悲伤，相识、别离，对于无法再度相见的恐惧、对于战争和冲突的无力感，以及其最终意识到、应该由自己来建立一个让所有人获得幸福的虚拟世界的使命——正是从这一刻开始，“辉夜”成为了“八千代”。</p>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-049.webp\" alt=\"辉夜姬-她并非冷漠，只是……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>纵使时光千载流转……</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-050.webp\" alt=\"辉夜姬-她并非冷漠，只是……2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>……你我二人终将再会。</figcaption>\n  </figure>\n</div>\n<p>在目睹这一切后，彩叶在八千代的呼唤下悠悠醒来，这一刻的她终于理解了辉夜所经历的一切，也终于追赶上了辉夜。故事结束了，即使没有辉夜，彩叶也可以得到一个“很好的结局”……但，她在这一刻察觉到了自己真正的心意；彩叶凝视着辉夜的脸，向她说出了自己发自心底的愿望：</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-028.webp\" alt=\"辉夜姬-想和辉夜在一起\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「想和辉夜在一起……」</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-017.webp\" alt=\"辉夜姬-我本以为就这样也无所谓了\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「我本以为，就这样结束，也没关系……」</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p><em>「想和辉夜在一起……」</em></p>\n<p><em>「我本以为，就这样结束，也没关系……」</em></p>\n<p>八千代哭了，积攒了八千年的泪水从辉夜的脸上滑落，两人分别哼唱起两首歌那重叠的旋律，她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/remember\">Remember</a>》终于得到了属于她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/reply\">Reply</a>》。</p>\n<p>话虽如此，月读空间的感知系统仍然很不完善，八千代抚摸着彩叶的手，既无法感受到彩叶的体温，也无法回味记忆当中松饼的甜蜜；面对来自爱人的愿望，彩叶意识到了自己的使命——她誓要与眼前的挚爱之人一起，共同迈向那个真正的Happy End。</p>\n<p>在这一愿望的驱动下，彩叶毅然踏上弃文从理的道路，为自己安排了难如登天的学习计划——她要利用不到10年的时间，成为若干相关科技领域的顶级专家，在读书期间就完成对于月读空间的感知系统的升级，并基于这些技术，制作出堪比机械飞升的合成人躯体，最终将辉夜/八千代的意识下载至机体，使其获得新生。</p>\n<p>十年后，已然功成名就的酒寄彩叶博士拥有了自己的研究所，也从哥哥和其他好朋友那里拉到了天文数字级的赞助；在朋友们的殷切期盼与八千代的歌声护佑下，那具有着熟悉面容与金色长发的合成人躯体，终于睁开了她的双眼；</p>\n<p>——而这一次，是真正的<strong>皆大欢喜，可喜可贺。</strong></p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-013.webp\" alt=\"辉夜姬-整的活连自己都看不下去了\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>钱扣七百多，号封一个月，惠方卷也没了（大雾）</figcaption>\n  </figure>\n<ul class=\"wiki-source-list\">\n<li><strong>变化能力</strong>：作为月人，辉夜的肉体有着地球人所不具备的超强能力，除了一天一个模样<del>、迅速地成长到对应彩叶性癖的14岁少女状态</del>，还能自由自在地变幻发色、肤色等等，甚至就连一跃跳下十几层台阶、整活生吞整根惠方卷也不在话下。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">但是两瓶能量饮料下肚就能满血复活的彩叶也不是一般地球人好吧。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>记忆里的旧居</strong>：辉夜对彩叶一见钟情时，她的身体大概处于十岁的状态，这时候的她所看到的房间里的一切都显得更大，而这时候彩叶的漱口杯里也只有一支牙刷。在辉夜开始直播后，她与彩叶的个人用品逐渐混淆，漱口杯里也多出了属于她的那一支牙刷。而在八千代于月读空间里复原的旧居中，或许是由于她仍然对彩叶心怀顾虑，担心对方不敢接受自己；又或许是她只是单纯地想还原最初的景象，这个记忆中的房间的尺寸被等比例放大，而漱口杯里也只有一支牙刷。当然，这一间屋子的细节还不止如此——例如小圆桌上堆满的可乐和薯片，就是两人在直播涨粉时一同享用过的食品<del>，只是八千代力有未逮，没能实装味觉，这些记忆里的食品终究是与松饼一样，吃了个寂寞</del>。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-042.webp\" alt=\"辉夜姬-一根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>初来乍到，一根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-039.webp\" alt=\"辉夜姬-两根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>不当外人，两根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-032.webp\" alt=\"辉夜姬-又变回了一根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>如履薄冰，又变回了一根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-009.webp\" alt=\"辉夜姬-爱吃的零食，虽然没味道\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>零食满桌，然而食之无味</figcaption>\n  </figure>\n</div>\n<ul class=\"wiki-source-list\">\n<li><strong>同一件T恤</strong>：彩叶的黑色旧T恤同样是贯穿全剧的重要意象——同一件衣服，穿在十岁外观的小辉夜身上犹如童装，穿在十四岁外观的辉夜身上显得很呆，但在八千代的身上，就显现出了莫名其妙的……呃……</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:180px\">\n    <img src=\"/assets/images/wiki/content/source-031.webp\" alt=\"辉夜姬-同一件T恤0\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>宝宝，可爱</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:320px\">\n    <img src=\"/assets/images/wiki/content/source-030.webp\" alt=\"辉夜姬-同一件T恤1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>呆呆的，也很可爱</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-029.webp\" alt=\"辉夜姬-同一件T恤2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>试图诱惑彩叶的吃人怪兽……</figcaption>\n  </figure>\n</div>\n<ul class=\"wiki-source-list\">\n<li><strong>是寻求母亲，还是寻求……？</strong>：不同于第三人称视角、情感表达较为含蓄的动画，官方小说则以彩叶为第一人称视角，以她的口吻加入了大量的内心戏。在这些内心戏中，彩叶不仅若干次地强调自己对于全年龄段（婴儿、幼儿、十岁孩童、十四岁孩童等）的辉夜的喜爱，甚至还在最后从八千代的歌声中，感受到了自己曾经渴望从生母身上获取的某些情感<del>，就差把<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/oo%E6%98%AF%E8%83%BD%E6%88%90%E4%B8%BA%E6%88%91%E6%AF%8D%E4%BA%B2%E7%9A%84%E5%A5%B3%E6%80%A7\" target=\"_blank\" rel=\"noopener noreferrer\">八千代是可以成为自己母亲的女人</a>给写在那儿了</del>。结合彩叶抚养辉夜的经历，这段经历也与官方MV「ray」当中的、小彩叶哭着从橱柜中扑向有着八千代眉目轮廓的辉夜的一幕相合，明确地表达了这对共轭母女(?)的彼此珍重与眷恋。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">我的女儿是看着我长大的妈妈，我的妈妈是我亲手养大的女儿，而且她们还是我的老婆，哇太爽了</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>真想再和你一起吃松饼啊</strong>：一般来说，标准的松饼会以面粉和鸡蛋为主要原料，通过泡打粉等实现松软口感，并加入糖等风味料进行调味；而彩叶为辉夜准备的穷鬼版“松饼”仅由面粉与水构成，这种寡淡的成品一般有另一个更贴切的名字——煎饼。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">然而，就是这么一款辉夜刚一进嘴就表示难吃到爆的粗劣食物，却在八千年的岁月里令她魂牵梦萦了无数次。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>是你的事，我便记得</strong>：辉夜的天真烂漫使其经常做出许多或滑稽、或匪夷所思的举动，而彩叶将这些行为统统记在心里。例如，辉夜曾经躲藏在橱柜中<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">kokodayo</span>，而彩叶在辉夜离开后的当夜便一扇扇地拉开橱柜，期待辉夜能够从其中现身；辉夜在两人搬入新居当天进餐时做出调皮的庆祝动作，这个动作也在后来辉夜复活演唱会时为彩叶所复刻。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n|<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-015.webp\" alt=\"辉夜姬-拉橱柜门1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>kokodayo~</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:230px\">\n    <img src=\"/assets/images/wiki/content/source-014.webp\" alt=\"辉夜姬-拉橱柜门2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>别藏了，快出来吧，拜托你……</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n|<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-011.webp\" alt=\"辉夜姬-泥鳅1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>辉夜的原版pose</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:215px\">\n    <img src=\"/assets/images/wiki/content/source-010.webp\" alt=\"辉夜姬-泥鳅2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>见大相框中彩叶的pose</figcaption>\n  </figure>\n</div>\n<p>与此相对应的是，辉夜也几乎记得彩叶对她说过的每一句话，譬如彩叶在对阵“黑玛瑙”3V3比赛期间说出的“要是你搞砸了，我就不管你了”，这句语气轻松的调侃后来成为了辉夜/八千代心中最深刻的梦魇之一。</p>\n<details class=\"wiki-source-hide\"><summary><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">搞砸了</span></summary><div><div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-023.webp\" alt=\"辉夜姬-搞砸了1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>再也不管你了</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:340px\">\n    <img src=\"/assets/images/wiki/content/source-024.webp\" alt=\"辉夜姬-搞砸了2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>求求你，不要……</figcaption>\n  </figure>\n</div></div></details>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"iroha","title":"酒寄彩叶","original":"酒寄彩葉","headline":"把过载的生活重新写成音乐，并负责让舞台真正运转的人。","summary":"17 岁高中生，独自承担学业与生活压力。她曾经写歌，却把音乐搁置；与辉夜相遇后以“彩P”的身份重拾创作，成为舞台背后的制作人。","aliases":["酒寄彩葉","彩P","Iroha"],"tags":["彩P","制作人","高中生"],"facts":[["年龄","17 岁"],["生日","5 月 11 日（社区资料）"],["身份","高中生／制作人／作曲者"],["活动名","彩P"],["声优","永濑安奈"]],"sections":[["人物简介",["酒寄彩叶是故事的现实侧主人公。她独自在东京承担学业、打工和生活支出，表面可靠到近乎无所不能，实际长期处在严重透支状态。","她曾经写歌，却因家庭与生活压力把音乐搁置。辉夜的出现打破了她精密而封闭的日程，也让“再次创作”变成无法回避的选择。"]],["能力与创作",["彩叶兼具作曲、演奏、游戏与运营能力。在“辉夜×彩P”组合中，她不仅写歌，也负责直播策划、资源安排和危机处理。","月读中的虚拟形象强调狐耳、和风与制作人属性，和现实中的学生形象形成对照。"]],["人物关系",["辉夜是彩叶重新拥抱音乐的契机，也是她第一次主动争取的未来。八千代起初是她仰慕的主播，后来则成为理解整段时间闭环的关键。"]]],"spoiler":["辉夜离开后，彩叶没有接受“就此结束”的结局，而是完成《Reply》并继续追查八千代。","理解八千代经历的漫长时间后，她转向相关科学领域，希望赋予对方能够感受现实的身体。十年后的成果构成作品的 Happy End。"],"relatedCharacters":["kaguya","yachiyo","akira","roka","mami"],"relatedTerms":["tsukuyomi","kassen","yachiyo-cup","reply"],"image":"/assets/images/wiki/entries/characters/iroha-reality.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"},"imageAlt":"酒寄彩叶现实形象清晰设定图","imageVariants":[{"id":"reality","label":"现实","image":"/assets/images/wiki/entries/characters/iroha-reality.webp","imageAlt":"酒寄彩叶现实形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"}},{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/iroha-tsukuyomi.webp","imageAlt":"酒寄彩叶月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（月夜见形象）"}}],"imageTarget":"assets/images/wiki/entries/characters/iroha-reality.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"iroha","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E9%85%92%E5%AF%84%E5%BD%A9%E5%8F%B6","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科：酒寄彩叶","url":"https://zh.moegirl.org.cn/%E9%85%92%E5%AF%84%E5%BD%A9%E5%8F%B6"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"kaguya","label":"辉夜"},{"kind":"character","slug":"yachiyo","label":"月见八千代"},{"kind":"character","slug":"akira","label":"帝アキラ"},{"kind":"character","slug":"roka","label":"绫䌷芦花"},{"kind":"character","slug":"mami","label":"谏山真实"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"},{"kind":"term","slug":"kassen","label":"KASSEN"},{"kind":"term","slug":"yachiyo-cup","label":"八千代杯"},{"kind":"term","slug":"reply","label":"Reply"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"酒寄彩葉","group":false},{"label":"译名","valueHtml":"酒寄彩叶","group":false},{"label":"别号","valueHtml":"彩P、168、彩姐、神、彩超人、心软叶、所长","group":false},{"label":"发色","valueHtml":"深蓝色","group":false},{"label":"瞳色","valueHtml":"绿","group":false},{"label":"年龄","valueHtml":"17","group":false},{"label":"生日","valueHtml":"5月11日<span class=\"wiki-source-category\">分类:5月11日</span>","group":false},{"label":"星座","valueHtml":"","group":false},{"label":"声优","valueHtml":"永濑安奈","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">高中生、泪痣、吊眼、科学家、作曲、音乐人、中长发、丸子头、长鬓角、白色短袜、水手服、温柔、认真、打工族、优等生、妈妈、del、母性、妹妹、黑幕、百合、黑幕</span><br>月读：<span class=\"wiki-source-traits\">短发、狐耳、花钿、和服、连帽衫、网袜、长靴、尾巴、电子琴，键盘</span>","group":false},{"label":"出身地区","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%BA%AC%E9%83%BD\" target=\"_blank\" rel=\"noopener noreferrer\">京都</a>？","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">与辉夜幸福地生活在一起的Happy End</span>","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"好友：<a class=\"wiki-source-link\" href=\"/wiki/characters/kaguya\">辉夜</a>、<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a><br>哥哥：<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">酒寄朝日</a>、闺蜜：<a class=\"wiki-source-link\" href=\"/wiki/characters/roka\">绫䌷芦花</a>、<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">谏山真实</a>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>毕竟，我经历了许多……我现在，说不定已经超过你了哦，八千代。</strong></big></blockquote>\n<p><strong>酒寄彩葉</strong>（<strong>酒寄 彩葉</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>初登场时的形象是“热爱打游戏的17岁普通女高中生”<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">普通说是</span>。</p>\n<p>由于某些原因，在与母亲爆发冲突后离家出走，独自来到东京过活。在他人面前是超一流模范生，不仅学业、体育、音乐样样全能，与周围人相处融洽，还能依靠打工独自负担学费和维持生计，甚至还在时下流行的竞技类网游《合战（KASSEN）》达到准职业级水准。</p>\n<p>话虽如此，彩叶的生活极为拮据，甚至会为购入一瓶能量饮料进行激烈的思想斗争。维持生计的代价是对身体的严重压榨，彩叶每天的平均睡眠时长仅3小时，经常会在课堂上睁着眼睛睡过去，周末日程不紧时的6小时睡眠被视为“奢侈”，且长期依靠口感粗劣的生命体征维持餐与能量饮料延续生命，几乎可以说是处于随时崩溃的边缘<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">说句超人不为过吧</span>。</p>\n<p>为了节省开支，彩叶原本居住在无需担保人、月租仅38,000日元（不足1,900人民币）、面积仅四叠半的老旧公寓中；后来在哥哥的担保下搬进了条件更好的顶层复式公寓<del>，但还是把旧公寓里能搬走的家具都搬走了，物尽其用</del>。</p>\n<p>与上述的“某个原因”相同，彩叶原本的志愿是东京大学的法学系，后来毅然弃文从理，最终成为了多领域的顶级科学家<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">。诺贝尔奖并非与彩叶无缘，而是彩叶的名字足以命名一个同等级的奖项</span>。</p>\n<p>是虚拟空间「月夜见」顶流主播兼管理员<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a>的狂热粉丝，甚至在卧室里为八千代的立牌专门设置了一个小小的神龛。</p>\n<p>有音乐经验，会作曲，但同样因为上述的“某个原因”而放弃。</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>酒寄彩叶出生在一个情况较为特殊的家庭中，她拥有一个较自己年长6岁的哥哥酒寄朝日，母亲酒寄红叶曾被亲生父母抛弃，父亲酒寄朝久则是被领养的孤儿。</p>\n<p>彩叶的母亲红叶极为精明强干，十分艰苦的早年经历与律师职业生涯使她形成了堪称执拗的性格，在家中扮演严母的形象；父亲朝久是一名作曲家，性格稳重温柔，他悉心陪伴彩叶，鼓励女儿发掘自己的音乐天赋，却在彩叶6岁时突然撒手人寰，时年仅37岁；哥哥朝日原本是个精力旺盛、调皮机灵的少年，但在父亲死后，他放弃了原本的足球爱好，开始家里蹲打游戏。</p>\n<p>父亲朝久去世后，母亲红叶没有向命运低头，而是一声不吭地肩负起抚养兄妹俩的重担，但兄妹的性格与关系仍然因为父亲的死而发生巨变——兄妹俩原本相互扶持，可哥哥朝日却在数年后忽然独自离家、外出打拼，这被彩叶误解为是背叛的表现；随母亲过活的彩叶无法理解母亲的表面强横，而母亲亦认为彩叶无法像自己一样承担责任，母女俩为此爆发激烈争吵；最终，彩叶抱着“母亲能做到的事情我也能”的想法，在初中三年级的冬天离开家乡，就此踏上独立生存的道路，誓要重走一遍母亲的过往，将自己的决心证明给母亲看。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-019.webp\" alt=\"辉夜姬-彩叶上课睡觉差点被抓\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>魂魄出窍</figcaption>\n  </figure>\n<p>在此期间，虚拟空间“月夜见”（下文称“月读空间”）及相关智能设备取得突破式发展，并与现实深度融合，成为最流行的时代产物，晋升为一个<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">疑似仅在本国便</span>拥有上亿用户的超级综合体。彩叶在这期间接触到了月读空间的管理员兼新手引导兼虚拟艺人月见八千代，她为对方的歌声与形象深深打动，成为八千代的狂热粉丝；她在生活中高度依赖八千代提供的精神价值<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，包括但不限于提神、镇定、健胃消食等</span>，甚至在后来将其视为自己的唯一寄托。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-012.webp\" alt=\"辉夜姬-梦开始的地方\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>电线杆子物语（不是）</figcaption>\n  </figure>\n<p>故事开始时，彩叶正就读于东京市内的某高中二年级，在学校里拥有<a class=\"wiki-source-link\" href=\"/wiki/characters/roka\">绫䌷芦花</a>与<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">谏山真实</a>两位好闺蜜，维持着住所-学校-打工的咖啡馆-住所的忙碌生活。虽然在表面上过着人人见了都得竖大拇指的硬核生活，可由于长期积累疲劳所导致的内耗，彩叶的精神已经接近崩溃边缘。</p>\n<p>暑假前的某夜，结束一天劳作的彩叶即便依靠八千代的歌声也难以提振精神，甚至开始不受控制地落泪。在归家的路上，彩叶撞见一颗滑落的流星，在许愿“给我钱”后，她在家门口遭遇了迸发出七彩光芒的电线杆，并从电线杆当中意外<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">并非意外</span>拾获了一个可爱的小婴儿。周遭环境的危险性使得彩叶决定将婴儿带回住处，她在使劲浑身解数也无法阻止婴儿哭泣后，终于恍然大悟，为婴儿哼唱八千代的出道曲《Remember》作为摇篮曲，终于让婴儿平静下来。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-033.webp\" alt=\"辉夜姬-十七岁的单亲母亲（？）\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>JK妈妈（？）</figcaption>\n  </figure>\n<p>经历了好一番破费、为成长速度惊人的婴儿购置基本用品后，彩叶在拾获婴儿的第三天惊讶地发现，这个被捡回来的孩子已经成长为了一个面貌大约十岁的超级美少女<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">萝莉控初见端倪</span>。彩叶与少女进行了一番艰难的沟通，期间，少女不仅吃光了摆在两人面前的所有食物，还自称是从月球来的外星人；在彩叶实在熬不住困意的当口，少女偷偷通过彩叶的个人电脑迅速学习了有关地球及互联网的知识，这令彩叶感到既荒谬又无语。</p>\n<p>次日，彩叶苏醒时发现少女不见，误以为这几天的经历是一场梦，随即惨遭打脸；无奈，她为又长大了一些的少女准备了粗劣的穷鬼版松饼，并在警告对方不要惹事后出门上学。然而，令她大跌眼镜的是，少女不仅尾随她跑出家门，一路追到她接受芦花和真实款待的咖啡厅，还鲸吞了本属于她的美味松饼谢礼；为了掩人耳目，她只得谎称少女是自己的表妹，还根据早些时候的交流为其命名为“辉夜”，并带着辉夜仓皇逃离现场。然而，这不是辉夜捅的唯一一个篓子——在彩叶的追问下，她发现辉夜用自己的积蓄购买了智能隐形眼镜，还准备了成本惊人而美味至极的料理。吃人嘴短加上没法退款，大破费的彩叶只得勉强答应辉夜，准许其在自己身边暂住，并引荐辉夜首次登入了月读空间。</p>\n<p>在与辉夜就月读空间的基础概念进行一番交流后，彩叶与辉夜一同前往八千代的迷你演唱会；在一如既往地被八千代的精美演出感动得一把鼻涕一把泪的同时，彩叶也获悉了八千代即将举办比拼涨粉量的“八千代杯”的消息。在乱入现场的顶流主播组合“黑玛瑙”的刺激下，性格直来直去的辉夜大声表示自己也要参与奖杯的争夺，这让彩叶感到十分紧张，但<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">同样是萝莉形态的</span>八千代随后在握手会上认真地向彩叶表达了感谢与支持。一方面是与八千代同台演出的诱惑，另一方面是辉夜笨拙而热切的恳求，彩叶最终答应了辉夜“一起找到那个Happy End”的邀请，与辉夜组成“辉夜x彩P”组合正式出道，作为辉夜的搭档，开始了两人的王道征途。</p>\n<p>辉夜似乎生来就是直播的料，她超强的行动力结合彩叶顶尖的运营能力，使得两人的涨粉数蒸蒸日上；由于彩叶需要兼顾学业，辉夜还拉上了同为人气主播的芦花与真实，向两人认真取经。芦花与真实同样欣赏辉夜这个“小表妹”的美丽与热情，并为辉夜帮助彩叶走出自我封闭、变得开朗而欣慰；她们没有深究辉夜的背景，但她们真心为彩叶的变化感到高兴。</p>\n<p>某日，过劳的彩叶被通宵直播的辉夜吵醒，终于在次日坚持不住而倒下；在从昏迷中醒来后，她发现辉夜已经尽可能为她安排好了一切事宜，还大哭着劝她好好休息。辉夜无法理解彩叶为何如此拼命，因此，彩叶向其讲述了自己与母亲的纠葛；辉夜为母女间的关系表现得十分动容，却也尊重了彩叶的想法。</p>\n<p>尽管已经使劲浑身解数，但两人组的涨粉速度距离第一名的“黑玛瑙”仍有巨大差距。就在辉夜对此感到苦恼的时候，“黑玛瑙”的队长帝明主动向两人发来了《合战》的3V3挑战书——其实，帝明的真实身份正是彩叶的哥哥朝日，他很早就注意到了妹妹与辉夜的活跃，虽然在嘴上叫嚣着要辉夜输给自己后嫁给自己为妻，实际上是想凭借自己超级大物的身份拉她们一把。</p>\n<p>比赛当日，被两人组拉来凑人头的真实因近距离目睹偶像，情绪过于激动而无法继续比赛；此时八千代突然乱入，作为替补队员加入了彩叶与辉夜的队伍<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然而此时芦花就在看台上，八千代的小心思昭然若揭</span>。在与“黑玛瑙”进行鏖战期间，彩叶被迫脱下自己用于掩盖身份的狐狸皮套，公开了与帝明的兄妹关系，并在最后理解了哥哥的良苦用心，解除了兄妹间的误会。</p>\n<p>由于实力差距实在不小，“黑玛瑙”精彩地赢下了《合战》3V3挑战，但彩叶与辉夜却凭借种种加成，以微弱优势获得了“八千代杯”的胜利。随后，彩叶委托哥哥朝日作为担保人，兑现与辉夜“搬进新居”的约定，姐妹俩搬进了环境更好的顶层公寓套间，还从揣面团开始、制作了一餐意面作为庆贺。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:375px\">\n    <img src=\"/assets/images/wiki/content/source-008.webp\" alt=\"辉夜姬-要不我和彩叶结婚算了\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「真是的，也许我应该和彩叶结婚呐。」「……哈！？」</figcaption>\n  </figure>\n<p>在与八千代联动演出的前夜，彩叶紧张得睡不着觉，而辉夜则是一如既往地钻进她的被窝，闻着辉夜的味道，彩叶难得地睡了个好觉。次日，两人在准备室与翩然降临的八千代相遇，趁着登台前的时机，彩叶询问八千代是否还会再演唱出道曲《Remember》，八千代则是含糊地表示“这首歌已经传达到了”，没有留给彩叶追问的机会。</p>\n<p>三人的联动演唱会取得了空前成功，辉夜甚至还借着绝佳的气氛向彩叶直球告白求婚，搞得彩叶脸红心跳；然而，三人所在的舞台却在这时遭遇奇怪人形的围攻，辉夜在接触到人形的瞬间失去知觉；虽然八千代迅速驱逐了人形，并表示会对此进行追查，但八千代和辉夜在意外发生前后的古怪表现却让彩叶生起疑心。</p>\n<p>相比起八千代的语焉不详，辉夜的故作镇定令彩叶更加不安。此时芦花与真实恰好发来助攻，在两人的鼓励下，彩叶破天荒地主动邀请辉夜去看烟火大会，收到了辉夜狂喜乱舞的回复。面对漫天烟花，辉夜认真询问了彩叶对于妈妈的看法，并向彩叶吐露了自己的真实身份——她确实是不甘无聊、逃出月球的月人公主，此前的插曲正是月人发出的引渡讯号，而她即将在下个月圆之夜离开——亦即公元2030年9月12日，农历八月十五，中秋节。面对仿佛在一瞬间变得成熟的辉夜，面对强打精神、说着鼓励自己的话的辉夜，彩叶感到如鲠在喉，仿佛心在滴血。</p>\n<p>返回住所后，辉夜立刻发布了隐退声明与毕业演唱会预告，而彩叶则将此前未能与爸爸一起完成的旧作找出，要为辉夜创作临别前的新歌。趁着辉夜休息的当口，彩叶找到了八千代和好朋友们，向他们告知了有关辉夜的真实身份，并计划在辉夜的毕业演唱会上迎击月人，试图挽留辉夜；好友们虽然对于这一事实感到有些意外，却一口答应下来。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:300px\">\n    <img src=\"/assets/images/wiki/content/source-020.webp\" alt=\"辉夜姬-当她离去的时候，向她递出手的人，一个是亲人，而另一个……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>当彩叶离去的时候，向她递出手的两个人，一个是哥哥，而另一个……</figcaption>\n  </figure>\n<p>毕业演唱会的日子很快到来。在演出开始前，辉夜将自己始终佩戴的奇特手环托付给了彩叶，作为从彩叶处收到自己名字的答礼。在演唱会开始前，辉夜私下询问了八千代，“如果自己是八千代的话，是否能将彩叶迷得更彻底”，得到了否定的答复<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">；然而，彩叶在片刻后同样私下询问八千代，“如果自己是八千代的话，辉夜会和自己说不想回去吗”，却收获了对方的惊讶，以及“原来你们是两情相悦啊”的奇怪答复</span>。</p>\n<p>演唱会随即开始，伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；彩叶在哥哥等人的支持下抵达了辉夜的舞台前，却仍然无法阻止月人带走辉夜。最终，月读空间中的辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝，而现实中的辉夜则紧紧地拥抱了彩叶，向她进行最后的告白，随即悄然消失。</p>\n<p>彩叶强打精神，对众人平静地表达感谢，然后登出了月读空间；她紧接着收到了辉夜的转账消息，也算是兑现了自己起初向流星许下的愿望。然而，这笔钱已经不重要了，彩叶失魂落魄地走过房间的每一处角落，试图寻回与辉夜曾经度过的时光。</p>\n<p>就这样，彩叶茶饭不思地度过了数日，终于恍然大悟、走出阴影，决定重启自己的人生，而与辉夜度过的经历则将成为一场美好的梦，激励她翻开新的篇章。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>……话是这么说，怎么可能就这样结束嘛——！</summary><div><p>倘若故事到此为止，那么这大概也就是一个拙劣的现代版竹取物语，而你彩叶姐是要带给所有人Happy End的超人，怎么可能会容许这种Bad End的发生！</p>\n<p>伴随着“怎么可能就这样结束啊啊啊！”的怒吼，彩叶推翻了自己为了虚假的“可喜可贺”所做的努力，她推辞了一切社交和学习计划，然后接通了来自妈妈的电话。在与妈妈爆发一番前所未有的争吵后，妈妈最终拐着弯儿表达了对彩叶的牵挂和理解，而终于抛下一切的彩叶也总算得以倾注全部时间和精力，在接下来的几天里完成了一首新的歌曲。</p>\n<p>带着煎熬、期待、对爸爸的追念以及对辉夜的眷恋，彩叶捧着辉夜留给自己的手环，向着月亮清唱出了这首刚刚完成的歌曲；思念的力量使得歌声跨越时空，成功传递给了月亮彼端的辉夜，而彩叶却在此时惊讶地发现，另有一个人的声音加入了合唱。</p>\n<p>宛如流星天启一般，彩叶忽然顿悟——她此前为辉夜所作、名为《Reply》的歌曲，有着一段与八千代的出道曲《Remember》相同的旋律；而刚刚加入合唱的人，正是她一直仰慕的八千代。</p>\n<p>自辉夜的演唱会结束以后，八千代也失踪了；不止如此，早在演唱会开始之前，八千代就仿佛人间蒸发、完全没有对月人进行任何干涉。面对重重谜团，彩叶在月读空间四处寻找，随后遭遇了八千代的奇特宠物——海兔FUSHI。在FUSHI的引导下，彩叶于现实中追索到了八千代的物理坐标——一座藏在某公寓楼当中的机房，机房的正中是一座水箱，其中漂浮着一颗竹笋般的奇特存在；彩叶从这里登入月读空间，发现自己出现在一处无名高塔的顶端，而面前背对着自己、长发垂地的少女，正是她苦苦追寻的八千代。</p>\n<p>面对彩叶“辉夜就是八千代吗”的疑问，八千代翩然而起，向彩叶讲述了自己的由来：辉夜在回到月球后，因听到彩叶的歌声而爆肝完成工作；尽管如此，这时的彩叶也已经垂垂老矣，因此辉夜便制造出能够穿越时空的竹笋飞船，准备返回彩叶年轻时的时代；然而，飞船在飞行途中不慎撞击陨石，误打误撞地返回了八千年前的地球，残存的能量只能塑造海兔FUSHI的身体，因此辉夜便通过FUSHI与外界交流；时光流转，人类进入互联网时代，辉夜终于等到机会，基于互联网和月人科技制造了“月读空间”，由此成为了八千代。</p>\n<p>话虽如此，面对八千代“这可没法用皆大欢喜，可喜可贺来干脆地收尾啊”的自嘲，彩叶不论如何也无法理解；她忍不住询问八千代为何能够一直笑着，却发现对方的颤抖逐渐从指尖蔓延至全身——八千代并不是一直笑着，只是漫长的生命令她无力垂泪；她没能兑现当初的诺言，她“搞砸了”，可她仍然以一副无比悲伤的表情，在心爱的彩叶面前强颜欢笑着。</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-003.webp\" alt=\"辉夜姬-……只是在强颜欢笑2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>那个耀眼的辉夜姬……</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-002.webp\" alt=\"辉夜姬-……只是在强颜欢笑\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>……现在已经是个老奶奶了。</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p>colspan=&quot;2&quot;</p>\n<p><em>「那个耀眼的辉夜姬……现在已经是个老奶奶了。」</em></p>\n<p>对于八千代、亦即经历了八千年岁月的辉夜来说，她自认为自己无法再以“辉夜”的身份与彩叶相处，而情愿以“八千代”的身份默默守护彩叶，甚至愿意为彩叶清除这段令人悲伤的记忆，而这引发了彩叶的强烈愤慨。彩叶执拗地要求八千代将过去的经历分享给自己<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，并在熬老太比赛中取得了第一名的好成绩</span>，而八千代则对此感到欣慰；她向彩叶分享了自己从绳纹时代到江户时代的种种愉快见闻，直至抵达系统运行时长上限，不得不强制休息。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-059.webp\" alt=\"辉夜姬-八千年份的思念\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>无量空处是0.2秒灌半年的垃圾信息，彩叶这八千年的记忆全是有效信息，无法细想</figcaption>\n  </figure>\n<p>八千代是休息了，但是她的故事并没有讲完；彩叶便转向八千代的小伙伴FUSHI，要求其将八千代的记忆完整地分享给自己。FUSHI的前身正是辉夜曾经制作的电子宠物“狗狗DOGE”，它同样见证了辉夜所经历的八千年，并为彩叶的觉悟所感动。在彩叶的恳求下，FUSHI在极短时间内将漫长岁月的记忆尽数输入彩叶的意识，而这一次，彩叶遭遇了宛如数百倍<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%BA%94%E6%9D%A1%E6%82%9F%23%E9%A2%86%E5%9F%9F%E5%B1%95%E5%BC%80%E3%80%8C%E6%97%A0%E9%87%8F%E7%A9%BA%E5%A4%84%E3%80%8D\" target=\"_blank\" rel=\"noopener noreferrer\">无量空处</a>的数据轰炸；她以辉夜/八千代的第一视角，目睹了爱人在漫长岁月里所经历的一切——欢笑、悲伤，相识、别离，对于无法再度相见的恐惧、对于战争和冲突的无力感，以及其最终意识到、应该由自己来建立一个让所有人获得幸福的虚拟世界的使命——正是从这一刻开始，“辉夜”成为了“八千代”。</p>\n<p>在目睹这一切后，彩叶在八千代的呼唤下悠悠醒来，这一刻的她终于理解了辉夜所经历的一切，也终于追赶上了辉夜。故事结束了，即使没有辉夜，彩叶也可以得到一个“很好的结局”……但，她在这一刻察觉到了自己真正的心意；彩叶凝视着辉夜的脸，向她说出了自己发自心底的愿望：</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-028.webp\" alt=\"辉夜姬-想和辉夜在一起\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「想和辉夜在一起……」</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-017.webp\" alt=\"辉夜姬-我本以为就这样也无所谓了\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「我本以为，就这样结束，也没关系……」</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p><em>「想和辉夜在一起……」</em></p>\n<p><em>「我本以为，就这样结束，也没关系……」</em></p>\n<p>八千代哭了，积攒了八千年的泪水从辉夜的脸上滑落，两人分别哼唱起两首歌那重叠的旋律，她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/remember\">Remember</a>》终于得到了属于她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/reply\">Reply</a>》。</p>\n<p>话虽如此，月读空间的感知系统仍然很不完善，八千代抚摸着彩叶的手，既无法感受到彩叶的体温，也无法回味记忆当中松饼的甜蜜；面对来自爱人的愿望，彩叶意识到了自己的使命——她誓要与眼前的挚爱之人一起，共同迈向那个真正的Happy End。</p>\n<p>在这一愿望的驱动下，彩叶毅然踏上弃文从理的道路，为自己安排了难如登天的学习计划——她要利用不到10年的时间，成为若干相关科技领域的顶级专家，在读书期间就完成对于月读空间的感知系统的升级，并基于这些技术，制作出堪比机械飞升的合成人躯体，最终将辉夜/八千代的意识下载至机体，使其获得新生。</p>\n<p>十年后，已然功成名就的酒寄彩叶博士拥有了自己的研究所，也从哥哥和其他好朋友那里拉到了天文数字级的赞助；在朋友们的殷切期盼与八千代的歌声护佑下，那具有着熟悉面容与金色长发的合成人躯体，终于睁开了她的双眼；</p>\n<p>——而这一次，是真正的<strong>皆大欢喜，可喜可贺。</strong></p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong>彩叶的名字与社交账号</strong>：彩叶的社交账号昵称为“色色”<del>日语环境下意为丰富多彩，不是你想的那个色色</del>，ID为@NihoheYCY。这里的“YCY”比较好理解，系八千代本名“ヤチヨ（<strong>Y</strong>a <strong>C</strong>hi <strong>Y</strong>o）”的罗马音首字母；而“Nihohe”则与彩叶的本名“いろは（Iroha）”有关——“いろは”同样可以写作“伊吕波”，《伊吕波歌》是一首方便孩童学习假名的传统和歌，这首歌的第一句的前六个字，便是“いろは<strong>にほへ</strong>（I Ro Ha <strong>Ni Ho He</strong>）”。</li>\n</ul>\n<p>《伊吕波歌》所表达的是佛教的无常观，慨叹世间万物皆无法做到永恒不变，结合昵称的“丰富多彩”，似乎是在向观众们暗示着彩叶对于人生的态度。<del>不过字面意思很简单，就是彩叶八千代贴贴。</del><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">当然了，考虑到八千代的老资历身份，你也可以说伊吕波歌就是她老人家当初因怀念彩叶而创作的歌谣。</span></p>\n<p>#另外，彩叶的名字“いろは”在古日语中有母亲的意思，其中“いろ”是一个前缀，最初表示同一母亲的血缘关系，也难怪彩叶会有那样的表现：留下小婴儿形态的辉夜并在第二天去购买婴儿用品而不是送去警察局（直接说路上捡到的也是可以的吧）、八千代为什么会用迷你形态（萝莉）和彩叶见面，想来也是参透了彩叶是萝莉控的本质（bushi）。</p>\n<ul class=\"wiki-source-list\">\n<li><strong>彩叶的游戏水平</strong>：在动画一开始，彩叶在游玩《合战》时，使用的是类似任天堂Switch的双持手柄；而在辉夜毕业演唱会前，彩叶的面前仅仅只有疑似经过辉夜改造的、用于歌曲伴奏的键盘；彩叶参与了对抗月人的战斗全程，而直到辉夜离开，她也始终没有使用过手柄——这意味着，彩叶不仅为辉夜出色地完成了伴奏，还全程用键盘打出了媲美<del>开挂的</del>“黑玛瑙”的炫酷操作。</li>\n</ul>\n<p><del>上一个抱着乐器在乱军丛中飞来飞去的高手是一位名叫<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E7%83%AD%E6%B0%94%E5%B7%B4%E8%90%A8%E6%8B%89\" target=\"_blank\" rel=\"noopener noreferrer\">热气巴萨拉</a>的男青年，虽说巴萨拉同样出自“<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%A6%81%E5%A1%9E7\" target=\"_blank\" rel=\"noopener noreferrer\">超时空</a>”字辈，在作品年代上是老前辈，但他本人在年龄上却比彩叶小了差不多一轮，可以看作是彩叶异父异母异时空的弟弟（大雾）。</del></p>\n<ul class=\"wiki-source-list\">\n<li><strong>是寻求母亲，还是寻求……？</strong>：不同于第三人称视角、情感表达较为含蓄的动画，官方小说则以彩叶为第一人称视角，以她的口吻加入了大量的内心戏。在这些内心戏中，彩叶不仅若干次地强调自己对于全年龄段（婴儿、幼儿、十岁孩童、十四岁孩童等）的辉夜的喜爱，甚至还在最后从八千代的歌声中，感受到了自己曾经渴望从生母身上获取的某些情感<del>，就差把<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/oo%E6%98%AF%E8%83%BD%E6%88%90%E4%B8%BA%E6%88%91%E6%AF%8D%E4%BA%B2%E7%9A%84%E5%A5%B3%E6%80%A7\" target=\"_blank\" rel=\"noopener noreferrer\">八千代是可以成为自己母亲的女人</a>给写在那儿了</del>。结合彩叶抚养辉夜的经历，这段经历也与官方MV「ray」当中的、小彩叶哭着从橱柜中扑向有着八千代眉目轮廓的辉夜的一幕相合，明确地表达了这对共轭母女(?)的彼此珍重与眷恋。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">我的女儿是看着我长大的妈妈，我的妈妈是我亲手养大的女儿，而且她们还是我的老婆，哇太爽了</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>你管这叫松饼？</strong>：一般来说，标准的松饼会以面粉和鸡蛋为主要原料，通过泡打粉等实现松软口感，并加入糖等风味料进行调味；而彩叶为辉夜准备的穷鬼版“松饼”仅由面粉与水构成，这种寡淡的成品一般有另一个更贴切的名字——煎饼。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">然而，就是这么一款辉夜刚一进嘴就表示难吃到爆的粗劣食物，却在八千年的岁月里令她魂牵梦萦了无数次。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>特别的感情</strong>：虽然在动画中表现得极为隐晦，但官方设定集介绍绫䌷芦花的段落却明确指出，芦花对彩叶怀揣<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%97%A0%E6%B3%95%E4%BC%A0%E8%BE%BE%E7%9A%84%E7%88%B1%E6%81%8B\" target=\"_blank\" rel=\"noopener noreferrer\">“特别的感情”</a>。基于这一备注，重看动画及官方MV，可以注意到芦花在与真实同屏时，眼角多次带泪的细节，以及时不时流露出的令人心酸的<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%8D%E4%B9%9F%E6%8C%BA%E5%A5%BD%E5%90%97\" target=\"_blank\" rel=\"noopener noreferrer\">挺好颜</a>。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">更绝望的是，芦花女士就连年度挺好颜的资格也无法独占，因为八千代也干了。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>是你的事，我便记得</strong>：辉夜的天真烂漫使其经常做出许多或滑稽、或匪夷所思的举动，而彩叶将这些行为统统记在心里。例如，辉夜曾经躲藏在橱柜中<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">kokodayo</span>，而彩叶在辉夜离开后的当夜便一扇扇地拉开橱柜，期待辉夜能够从其中现身；辉夜在两人搬入新居当天进餐时做出调皮的庆祝动作，这个动作也在后来辉夜复活演唱会时为彩叶所复刻。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n|<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-015.webp\" alt=\"辉夜姬-拉橱柜门1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>kokodayo~</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:230px\">\n    <img src=\"/assets/images/wiki/content/source-014.webp\" alt=\"辉夜姬-拉橱柜门2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>别藏了，快出来吧，拜托你……</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n|<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-011.webp\" alt=\"辉夜姬-泥鳅1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>辉夜的原版pose</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:215px\">\n    <img src=\"/assets/images/wiki/content/source-010.webp\" alt=\"辉夜姬-泥鳅2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>见大相框中彩叶的pose</figcaption>\n  </figure>\n</div>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">与此相对应的是，辉夜也几乎记得彩叶对她说过的每一句话，譬如彩叶在对阵“黑玛瑙”3V3比赛期间说出的“要是你搞砸了，我就不管你了”，这句语气轻松的调侃后来成为了辉夜/八千代心中最深刻的梦魇之一。</span></p>\n<details class=\"wiki-source-hide\"><summary><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">搞砸了</span></summary><div><div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-023.webp\" alt=\"辉夜姬-搞砸了1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>再也不管你了</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:340px\">\n    <img src=\"/assets/images/wiki/content/source-024.webp\" alt=\"辉夜姬-搞砸了2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>求求你，不要……</figcaption>\n  </figure>\n</div></div></details>\n<ul class=\"wiki-source-list\">\n<li><strong>无处不在的“168”</strong>：动画内外的许多场景都出现了与彩叶名字谐音的数字“168”，包括但不限于二人组刚开始涨粉时的排名（把图反过来看）、两人计划租新房时的咨询电话、辉夜获取首次直播收益的金额、歌曲《Remember》的bpm、线下剧院限时放映的总时长（7天*24小时=168）、众筹项目“超辉夜祭”最高赞助档的定价（168,000日元）、等等，甚至就连官推也在关注数抵达168,000时特地发了庆祝。可以说，彩叶是被制作组的大家无处不在地喜爱着的。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n|<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:220px\">\n    <img src=\"/assets/images/wiki/content/source-025.webp\" alt=\"辉夜姬-如果把图中的8910倒过来的话……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>8910倒过来看就是0168</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:220px\">\n    <img src=\"/assets/images/wiki/content/source-005.webp\" alt=\"辉夜姬-连租房电话也是168\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>整个号码的谐音是“（我）所爱的-彩叶-爱人（夫妇）”</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:235px\">\n    <img src=\"/assets/images/wiki/content/source-006.webp\" alt=\"辉夜姬-连收益都是爱你的数字\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>整个收益的谐音是“和彩叶一起出发”</figcaption>\n  </figure>\n</div>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:酒寄姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"yachiyo","title":"月见八千代","original":"月見ヤチヨ","headline":"月读的管理员、顶级主播，以及一场跨越八千年的等待。","summary":"月读的管理者与顶级主播，被称作“能唱、能跳、还能分身的 8000 岁神秘 AI”。她的歌曾深深影响彩叶，也守望着空间里的创作者。","aliases":["月見ヤチヨ","Runami Yachiyo","ycy"],"tags":["空间管理者","顶级主播","神秘 AI"],"facts":[["自称年龄","8000 岁以上"],["身份","月读管理员／虚拟歌手／主播"],["活动范围","虚拟空间“月读”"],["代表歌曲","Remember、星降る海"],["声优","早见沙织"]],"sections":[["人物简介",["月见八千代与月读几乎同时进入公众视野。她能歌善舞，也能以分身承担管理员、新手引导与导航等职责，因此被包装为“8000 岁神秘 AI”。","她真心享受创作者在月读中分享快乐的状态，并把维持这个空间视为自己的责任。"]],["舞台与管理者身份",["八千代既是偶像，也是平台本身的象征。她举办八千代杯、参与联动演出，并在辉夜和彩叶的成长中保持若即若离的关注。","《Remember》代表等待与记忆；当《Reply》出现后，两首歌共同承担了跨越时间的叙事功能。"]],["与彩叶、辉夜",["彩叶是八千代的重要观众，辉夜则让两人的关系从单向仰慕变成复杂的时间回环。无剧透阅读时，可以把三人的关系理解为“歌手—制作人—平台守望者”。"]]],"spoiler":["八千代实际上是经历漫长时间后的辉夜。返航后的辉夜试图回到彩叶身边，却误入约八千年前，只能借助新的身体与网络逐步建立月读。","她长期以“八千代”身份守望彩叶，既来自责任，也来自对自己已经不再是昔日辉夜的自卑。彩叶的选择最终打破这种自我否定。"],"relatedCharacters":["kaguya","iroha","fushi","doge"],"relatedTerms":["tsukuyomi","yachiyo-cup","remember","reply"],"image":"/assets/images/wiki/entries/characters/yachiyo-tsukuyomi.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"},"imageAlt":"月见八千代清晰角色设定图","imageVariants":[{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/yachiyo-tsukuyomi.webp","imageAlt":"月见八千代清晰角色设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"}}],"imageTarget":"assets/images/wiki/entries/characters/yachiyo-tsukuyomi.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"yachiyo","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E6%9C%88%E8%A7%81%E5%85%AB%E5%8D%83%E4%BB%A3","standalone":true},"sourceLinks":[{"label":"官方角色 PV（X）","url":"https://x.com/Cho_KaguyaHime/status/1987490353709043948"},{"label":"萌娘百科：月见八千代","url":"https://zh.moegirl.org.cn/%E6%9C%88%E8%A7%81%E5%85%AB%E5%8D%83%E4%BB%A3"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"kaguya","label":"辉夜"},{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"character","slug":"fushi","label":"FUSHI"},{"kind":"character","slug":"doge","label":"犬DOGE"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"},{"kind":"term","slug":"yachiyo-cup","label":"八千代杯"},{"kind":"term","slug":"remember","label":"Remember"},{"kind":"term","slug":"reply","label":"Reply"}],"songs":[{"id":"song-ex-otogibanashi","title":"Ex-Otogibanashi","type":"主题曲","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"original","note":"作品主题曲，标题呼应“超越童话”。"},{"id":"song-ray","title":"ray 超かぐや姫！Version","type":"片尾曲","creator":"藤原基央／TAKU INOUE 编曲","performer":"辉夜、月见八千代","category":"cover","note":"改编自 BUMP OF CHICKEN《ray》的电影版本。"},{"id":"song-remember","title":"Remember","type":"插入歌","creator":"真崎エリカ／yuigot","performer":"月见八千代","category":"original","note":"关于等待、记忆与时间回声的核心歌曲。"},{"id":"song-starry-sea","title":"星降る海","type":"插入歌","creator":"Aqu3ra","performer":"月见八千代","category":"original","note":"由 Aqu3ra 作词、作曲及编曲。"},{"id":"song-world-is-mine","title":"ワールドイズマイン CPK! Remix","type":"插入歌","creator":"ryo (supercell)","performer":"辉夜、月见八千代","category":"remix","note":"VOCALOID 经典曲目的 CPK! 重混音。"},{"id":"song-lonely-universe","title":"ロンリーユニバース","type":"翻唱曲","creator":"Aqu3ra","performer":"月见八千代","category":"cover","note":"月见八千代的官方唱见企划曲。"}],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"月見ヤチヨ","group":false},{"label":"译名","valueHtml":"月见八千代","group":false},{"label":"别号","valueHtml":"ycy、八千代大人、yachi8000、万代减两千、老资历","group":false},{"label":"多种发色","valueHtml":"渐变$（银色→粉色）","group":false},{"label":"多种瞳色","valueHtml":"渐变$（上粉下青）","group":false},{"label":"年龄","valueHtml":"8000<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">有余</span>","group":false},{"label":"声优","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%97%A9%E8%A7%81%E6%B2%99%E7%BB%87\" target=\"_blank\" rel=\"noopener noreferrer\">早见沙织</a>","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">AI姬、虚拟人、音乐人、双马尾、环形辫、内层挑染、温柔、认真、执着、外柔内刚、妈妈、黑幕、自卑、黑幕、沉重、黑幕、百合、黑幕</span>","group":false},{"label":"出身地区","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">月球</span>","group":false},{"label":"活动范围","valueHtml":"虚拟空间「月夜见」","group":false},{"label":"个人状态","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">与彩叶幸福地生活在一起的Happy End</span>","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"好友：<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\"><a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%96%E5%8F%A6%E6%88%91\" target=\"_blank\" rel=\"noopener noreferrer\">另一个我</a>：<a class=\"wiki-source-link\" href=\"/wiki/characters/kaguya\">辉夜</a></span>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>八百代们，诸位神明，今晚玩得还开心吗？</strong></big></blockquote>\n<p><strong>月见八千代</strong>（<strong>月見 ヤチヨ</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>\n<p>#其姓氏【月見】 中的“月”从日本本土发音“つき（tuki/tsuki）”更换成了来自拉丁语“lunar”的“るな(Runa）”。</p>"},{"id":"source-intro","title":"简介","html":"<p>初登场时的形象是“虚拟空间「月夜见」的管理员兼顶流主播”。</p>\n<p>自称是有着8000岁年龄、能歌善舞的神秘AI，与虚拟空间「月夜见」一同出现，凭借分身能力同时担任管理员、新手引导、各处导航等职务，以及作为虚拟艺人定期进行直播。</p>\n<p>虽说设定听起来相当离谱，但真实身份无人知晓，围绕其身世有着各种各样的传闻。（多企业合作说、海外国家项目说、电子幽灵说……）</p>\n<p>深深地爱着任何人都能自由进行创作活动的「月夜见」，其本人也享受着这种无忧无虑、分享快乐的幸福生活。然而……</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>在故事正式开始的数年前，虚拟空间“月夜见”（下文称“月读空间”）及相关智能设备取得突破式发展，神秘的AI歌姬·月见八千代亦伴随月读空间的实装而正式出道。作为月读空间的管理员，八千代致力于为用户营造一个轻松、纵情地享受各类娱乐的场所，同时她本人也作为月读空间的主播保持活跃。在她的努力下，月读空间得到迅速发展，成为最流行的时代产物，并逐渐接入现实生活的方方面面，晋升为一个<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">疑似仅在本国便</span>拥有上亿用户、其虚拟货币“福币（FUJI）”也可以在现实中流通的超级综合体。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-left\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-034.webp\" alt=\"辉夜姬-八千代向屏幕前的观众-彩叶打招呼\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>这一幕既是向着屏幕前的各位打招呼，也是向着荧屏下的彩叶打招呼</figcaption>\n  </figure>\n<p>此时，我们的主人公<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>同学正在东京独自一人过活，家庭的缺位、母爱的缺失与生活的压力致使她压力山大，而月读空间与八千代则成为了她难得的消遣与寄托。作为八千代的狂热粉丝，彩叶在生活中高度依赖八千代提供的精神价值<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，包括但不限于提神、镇定、健胃消食等</span>，甚至在后来将其视为自己的唯一支柱；而月读空间的超高自由度也得以让她在享受娱乐的同时赚些小钱、以便填补开支。</p>\n<p>故事开始时，彩叶正就读于东京都立川市内的某高中二年级，在学校里拥有绫䌷芦花与谏山真实两位好闺蜜，维持着住所-学校-打工的咖啡馆-住所的忙碌生活。虽然在表面上过着人人见了都得竖大拇指的硬核生活，可由于长期积累疲劳所导致的内耗，彩叶的精神已经接近崩溃边缘。</p>\n<p>暑假前的某夜，结束一天劳作的彩叶即便依靠八千代的歌声也难以提振精神，甚至开始不受控制地落泪。在归家的路上，彩叶撞见一颗滑落的流星，在许愿“给我钱”后，她在家门口遭遇了迸发出七彩光芒的电线杆，并从电线杆当中意外<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">并非意外</span>拾获了一个可爱的小婴儿。周遭环境的危险性使得彩叶决定将婴儿带回住处，她在使劲浑身解数也无法阻止婴儿哭泣后，终于恍然大悟，为婴儿哼唱八千代的出道曲《Remember》作为摇篮曲，终于让婴儿平静下来。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-037.webp\" alt=\"辉夜姬-从此我们再也没有听说过邻居的下落\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>从此，我们再也没有听说过这位敲墙邻居的下落<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">。南无三，今天也为您带来月读空间的黑暗真实</span></figcaption>\n  </figure>\n<p>几乎是一天一个样，神秘的婴儿迅速长大，由于其自称来自月球，彩叶便以课本上的《竹取物语》为灵感，为其取名“辉夜”。小小的辉夜为彩叶的生活带来了大大的麻烦，话虽如此，彩叶却不论如何也无法对美丽又可爱的辉夜狠下心来，而是准许其在自己身边暂住，还引荐辉夜首次登入了月读空间<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，反正钱已经花了，也没法退</span>。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-016.webp\" alt=\"辉夜姬-我和我的首次相遇\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>愉快地向着刚建号的辉夜跑来的八千代，可以看到她本人、她胸前的海鞘饰物和肩头的海兔FUSHI都是在笑着的</figcaption>\n  </figure>\n<p>在引导辉夜完成新手教程后，八千代愉快地目送辉夜进入了月读空间；候在门口的彩叶与辉夜就这个虚拟世界的基础概念进行了一番介绍，两人随即前往八千代的迷你演唱会，准备欣赏今夜的演出——功夫不负有心人，彩叶这次可是带着握手券的，她对这场演出抱着万分的期待。</p>\n<p>在观众们热切的倒计时中，万众瞩目的八千代准时出现在高高的鸟居舞台之上，她愉快地向着各位莅临的神明大人们问好，并献上了一曲幸福洋溢的《<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%98%9F%E9%99%8D%E3%82%8B%E6%B5%B7\" target=\"_blank\" rel=\"noopener noreferrer\">星降る海</a>》。接着，八千代向观众们公布了自己即将举办的活动“八千代杯”——这是一场比拼主播涨粉数量的活动，最终的冠军将会获得与八千代一起办联动演唱会的机会。由于八千代此前从来没有进行过合唱演唱会，这一消息对于彩叶这种粉丝头子来说无异是一枚重磅炸弹。</p>\n<p>话音未落，月读空间粉丝数第一的顶流组合“黑玛瑙”狂气登场。面对气势逼人的“黑玛瑙”队长·帝明的邀约，八千代委婉化解尴尬，而性格天真直率的辉夜则是按捺不住情绪，向着八千代大声表示自己也要参与奖杯的争夺。</p>\n<p>辉夜的胡闹让彩叶尴尬万分，但就在两人下线之前，八千代却忽然<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">以小萝莉形态</span>出现在彩叶面前，她牵住彩叶的手，向对方一直以来的支持表达感谢；乱了阵脚的彩叶机械地应声答复、随即登出，而八千代则是略带寂寞地向着彩叶离去的背影，露出了一抹意味深长的笑。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-044.webp\" alt=\"辉夜姬-……谢谢你一直来看我\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>八千代与FUSHI的表情完全不同，是什么意思呢？</figcaption>\n  </figure>\n<p>一方面是与八千代同台演出的诱惑，另一方面是辉夜笨拙而热切的恳求，彩叶最终答应了辉夜的邀请，与辉夜组成“辉夜x彩P”组合正式出道，作为辉夜的搭档，开始了两人的王道征途。</p>\n<p>辉夜似乎生来就是直播的料，她超强的行动力结合彩叶顶尖的运营能力，使得两人的涨粉数蒸蒸日上；然而，纵使两人使劲浑身解数，“辉夜x彩P”的涨粉速度距离高居榜首的“黑玛瑙”仍有巨大差距。就在辉夜对此感到苦恼的时候，“黑玛瑙”的队长帝明主动向两人发来了《合战》的3V3挑战书——其实，帝明的真实身份正是彩叶的哥哥朝日，他很早就注意到了妹妹与辉夜的活跃，虽然在嘴上叫嚣着要辉夜输给自己后嫁给自己为妻，实际上是想凭借自己超级大物的身份拉她们一把。</p>\n<p>比赛当日，被两人组拉来凑人头的真实因近距离目睹偶像，情绪过于激动而无法继续比赛；就在两人一筹莫展时，八千代突然从天而降，作为替补加入了彩叶与辉夜的队伍<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然而此时芦花就在看台上，八千代的小心思昭然若揭</span>。“黑玛瑙”毕竟是正儿八经的职业选手，为弥补实力差距，八千代的面板属性有所上调，但彩叶仍然不抱什么希望；话虽如此，这个临时拼凑的三人组还是各显神通、打出了属于她们的风采。</p>\n<p>由于游戏理解差距实在很大，“黑玛瑙”精彩地赢下了《合战》3V3挑战，但彩叶与辉夜却凭借种种加成，以微弱优势获得了“八千代杯”的胜利。赛后，<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">依然是小萝莉形态的</span>八千代从天而降，向两人表示庆贺；面对辉夜“如何才能像你一样”的询问，八千代闪烁其词，却表示辉夜“你很强大是因为你就是你”。</p>\n<p>在与八千代联动演出的前夜，彩叶紧张得睡不着觉，而辉夜则是一如既往地钻进她的被窝，闻着辉夜的味道，彩叶难得地睡了个好觉。次日，两人在准备室与翩然降临的八千代相遇，趁着登台前的时机，彩叶询问八千代是否还会再演唱出道曲《Remember》，八千代则是含糊地表示“这首歌已经传达到了”，没有留给彩叶追问的机会。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-007.webp\" alt=\"辉夜姬-这八千年的星压抑……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>碰瓷（不是）</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-035.webp\" alt=\"辉夜姬-你挡得住吗？\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>“晓看天色暮看云”</figcaption>\n  </figure>\n<p>三人的联动演唱会取得了空前成功，辉夜甚至还借着绝佳的气氛向彩叶直球告白求婚，搞得彩叶脸红心跳；然而，三人所在的舞台却在这时遭遇奇怪人形的围攻，辉夜在接触到人形的瞬间失去知觉；虽然八千代迅速驱逐了人形，并表示会对此进行追查，但八千代和辉夜在意外发生前后的古怪表现却让彩叶生起疑心。</p>\n<p>相比起八千代的语焉不详，辉夜的故作镇定令彩叶更加不安。在好友们的助攻下，彩叶破天荒地主动邀请辉夜去看烟火大会，并从辉夜口中得知了对方的真实身份——辉夜确实是不甘无聊、逃出月球的月人公主，此前的插曲正是月人发出的引渡讯号，而她即将在下个月圆之夜离开——亦即公元2030年9月12日，农历八月十五，中秋节。面对仿佛在一瞬间变得成熟的辉夜，面对强打精神、说着鼓励自己的话的辉夜，彩叶感到如鲠在喉，仿佛心在滴血。</p>\n<p>返回住所后，辉夜立刻发布了隐退声明与毕业演唱会预告，而彩叶则将此前未能与爸爸一起完成的旧作找出，要为辉夜创作临别前的新歌。趁着辉夜休息的当口，彩叶找到了八千代和好朋友们，向他们告知了有关辉夜的真实身份，并计划在辉夜的毕业演唱会上迎击月人，试图挽留辉夜；好友们虽然对于这一事实感到有些意外，却一口答应下来。</p>\n<p>毕业演唱会的日子很快到来。在演出开始前，辉夜将自己始终佩戴的奇特手环托付给了彩叶，作为从彩叶处收到自己名字的答礼。在演唱会开始前，辉夜私下询问了八千代，“如果自己是八千代的话，是否能将彩叶迷得更彻底”，得到了否定的答复<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">；然而，彩叶在片刻后同样私下询问八千代，“如果自己是八千代的话，辉夜会和自己说不想回去吗”，却收获了对方的惊讶，以及“原来你们是两情相悦啊”的奇怪答复</span>。</p>\n<p>演唱会随即开始，伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；彩叶在哥哥等人的支持下抵达了辉夜的舞台前，却仍然无法阻止月人带走辉夜（事实上，月人将此视为某种祭祀，在辉夜歌唱完毕后瞬间传送至辉夜面前）。最终，月读空间中的辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝，而现实中的辉夜则紧紧地拥抱了彩叶，向她进行最后的告白，随即悄然消失。</p>\n<p>彩叶强打精神，对众人平静地表达感谢，然后登出了月读空间；她紧接着收到了辉夜的转账消息，也算是兑现了自己起初向流星许下的愿望。然而，这笔钱已经不重要了，彩叶失魂落魄地走过房间的每一处角落，试图寻回与辉夜曾经度过的时光。</p>\n<p>就这样，彩叶茶饭不思地度过了数日，终于恍然大悟、走出阴影，决定重启自己的人生，而与辉夜度过的经历则将成为一场美好的梦，激励她翻开新的篇章。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>……这最后几段描述连八千代的影儿都没了，这叫什么可喜可贺！？</summary><div><p>倘若故事到此为止，那么这大概也就是一个拙劣的现代版竹取物语，而你彩叶姐是要带给所有人Happy End的超人，怎么可能会容许这种Bad End的发生！</p>\n<p>伴随着“怎么可能就这样结束啊啊啊！”的怒吼，彩叶推翻了自己为了虚假的“可喜可贺”所做的努力，她推辞了一切社交和学习计划，然后接通了来自妈妈的电话。在与妈妈爆发一番前所未有的争吵后，妈妈最终拐着弯儿表达了对彩叶的牵挂和理解，而终于抛下一切的彩叶也总算得以倾注全部时间和精力，在接下来的几天里完成了一首新的歌曲。</p>\n<p>带着煎熬、期待、对爸爸的追念以及对辉夜的眷恋，彩叶捧着辉夜留给自己的手环，向着月亮清唱出了这首刚刚完成的歌曲；思念的力量使得歌声跨越时空，成功传递给了月亮彼端的辉夜，而彩叶却在此时惊讶地发现，另有一个人的声音加入了合唱。</p>\n<p>宛如流星天启一般，彩叶忽然顿悟——她此前为辉夜所作、名为《Reply》的歌曲，有着一段与八千代的出道曲《Remember》相同的旋律；而刚刚加入合唱的人，正是她一直仰慕的八千代。</p>\n<p>自辉夜的演唱会结束以后，八千代也失踪了；不止如此，早在演唱会开始之前，八千代就仿佛人间蒸发、完全没有对月人进行任何干涉。面对重重谜团，彩叶在月读空间四处寻找，随后遭遇了八千代的奇特宠物——海兔FUSHI。在FUSHI的引导下，彩叶于现实中追索到了八千代的物理坐标——一座藏在某公寓楼当中的机房，机房的正中是一座水箱，其中漂浮着一颗竹笋般的奇特存在；彩叶从这里登入月读空间，发现自己出现在一处无名高塔的顶端，而面前背对着自己、长发垂地的少女，正是她苦苦追寻的八千代。</p>\n<p>面对彩叶“辉夜就是八千代吗”的疑问，八千代翩然而起，向彩叶讲述了自己的由来：辉夜在回到月球后，因听到彩叶的歌声而爆肝完成工作；尽管如此，这时的彩叶也已经垂垂老矣，因此辉夜便制造出能够穿越时空的竹笋飞船，准备返回彩叶年轻时的时代；然而，飞船在飞行途中不慎撞击陨石，误打误撞地返回了八千年前的地球，残存的能量只能塑造海兔FUSHI的身体，因此辉夜便通过FUSHI与外界交流；时光流转，人类进入互联网时代，辉夜终于等到机会，基于互联网和月人科技制造了“月读空间”，由此成为了八千代。</p>\n<p>话虽如此，面对八千代“这可没法用皆大欢喜，可喜可贺来干脆地收尾啊”的自嘲，彩叶不论如何也无法理解；她忍不住询问八千代为何能够一直笑着，却发现对方的颤抖逐渐从指尖蔓延至全身——八千代并不是一直笑着，只是漫长的生命令她无力垂泪；她没能兑现当初的诺言，她“搞砸了”，可她仍然以一副无比悲伤的表情，在心爱的彩叶面前强颜欢笑着。</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-003.webp\" alt=\"辉夜姬-……只是在强颜欢笑2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>那个耀眼的辉夜姬……</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-002.webp\" alt=\"辉夜姬-……只是在强颜欢笑\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>……现在已经是个老奶奶了。</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p>colspan=&quot;2&quot;</p>\n<p><em>「那个耀眼的辉夜姬……现在已经是个老奶奶了。」</em></p>\n<p>对于八千代、亦即经历了八千年岁月的辉夜来说，她自认为自己无法再以“辉夜”的身份与彩叶相处，而情愿以“八千代”的身份默默守护彩叶，甚至愿意为彩叶清除这段令人悲伤的记忆，而这引发了彩叶的强烈愤慨。彩叶执拗地要求八千代将过去的经历分享给自己<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，并在熬老太比赛中取得了第一名的好成绩</span>，而八千代则对此感到欣慰；她向彩叶分享了自己从绳纹时代到江户时代的种种愉快见闻，直至抵达系统运行时长上限，不得不强制休息。</p>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-043.webp\" alt=\"辉夜姬-小小的眼睛里……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>十岁时的她，对她一见钟情，而在她那小小的眼睛里……</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-001.webp\" alt=\"辉夜姬-……一切都是大大的\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>……她所看到的一切，都是大大的。</figcaption>\n  </figure>\n</div>\n<p>八千代是休息了，但是她的故事并没有讲完；彩叶便转向八千代的小伙伴FUSHI，要求其将八千代的记忆完整地分享给自己。FUSHI的前身正是辉夜曾经制作的电子宠物“狗狗DOGE”，它同样见证了辉夜所经历的八千年，并为彩叶的觉悟所感动。在彩叶的恳求下，FUSHI在极短时间内将漫长岁月的记忆尽数输入彩叶的意识，而这一次，彩叶遭遇了宛如数百倍无量空处的数据轰炸；她以辉夜/八千代的第一视角，目睹了爱人在漫长岁月里所经历的一切——欢笑、悲伤，相识、别离，对于无法再度相见的恐惧、对于战争和冲突的无力感，以及其最终意识到、应该由自己来建立一个让所有人获得幸福的虚拟世界的使命——正是从这一刻开始，“辉夜”成为了“八千代”。</p>\n<p>在目睹这一切后，彩叶在八千代的呼唤下悠悠醒来，这一刻的她终于理解了辉夜所经历的一切，也终于追赶上了辉夜。故事结束了，即使没有辉夜，彩叶也可以得到一个“很好的结局”……但，她在这一刻察觉到了自己真正的心意；彩叶凝视着辉夜的脸，向她说出了自己发自心底的愿望：</p>\n<p>-</p>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-028.webp\" alt=\"辉夜姬-想和辉夜在一起\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「想和辉夜在一起……」</figcaption>\n  </figure>\n</div>\n<div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:400px\">\n    <img src=\"/assets/images/wiki/content/source-017.webp\" alt=\"辉夜姬-我本以为就这样也无所谓了\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「我本以为，就这样结束，也没关系……」</figcaption>\n  </figure>\n</div>\n<p>-</p>\n<p><em>「想和辉夜在一起……」</em></p>\n<p><em>「我本以为，就这样结束，也没关系……」</em></p>\n<p>八千代哭了，积攒了八千年的泪水从辉夜的脸上滑落，两人分别哼唱起两首歌那重叠的旋律，她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/remember\">Remember</a>》终于得到了属于她的《<a class=\"wiki-source-link\" href=\"/wiki/terms/reply\">Reply</a>》。</p>\n<p>话虽如此，月读空间的感知系统仍然很不完善，八千代抚摸着彩叶的手，既无法感受到彩叶的体温，也无法回味记忆当中松饼的甜蜜；面对来自爱人的愿望，彩叶意识到了自己的使命——她誓要与眼前的挚爱之人一起，共同迈向那个真正的Happy End。</p>\n<p>在这一愿望的驱动下，彩叶毅然踏上弃文从理的道路，为自己安排了难如登天的学习计划——她要利用不到10年的时间，成为若干相关科技领域的顶级专家，在读书期间就完成对于月读空间的感知系统的升级，并基于这些技术，制作出堪比机械飞升的合成人躯体，最终将辉夜/八千代的意识下载至机体，使其获得新生。</p>\n<p>十年后，已然功成名就的酒寄彩叶博士拥有了自己的研究所，也从哥哥和其他好朋友那里拉到了天文数字级的赞助；在朋友们的殷切期盼与八千代的歌声护佑下，那具有着熟悉面容与金色长发的合成人躯体，终于睁开了她的双眼；</p>\n<p>——而这一次，是真正的<strong>皆大欢喜，可喜可贺。</strong></p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong>分身能力</strong>：作为“漂泊于电子海洋的歌姬”，八千代能够充分利用月读空间的属性，为自己构造若干同时存在的分身，营造浪漫而梦幻的视觉效果<del>，此时似乎可以通过FUSHI伴随哪一具躯体来识别本尊</del>；事实上，这种能力是基于她身为月人的属性演变而来，且不单纯止于视觉效果。例如，在故事的末尾，当辉夜/八千代借助合成人躯体重获新生时，这具躯体的意识便是从八千代/辉夜本尊分出来的一部分——八千代始终都是那个活泼好动的辉夜，而历经八千年岁月的辉夜也多了一份八千代独有的妩媚与从容。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">话虽如此，一人扮两角确实好玩，而彩叶与她也确实乐在其中。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong><del>八千代的大手</del></strong>：在了解了八千代的真实经历，进而重头回望故事时，可以发现剧组塞了许多或让人细思极恐、或让人心痒难耐的小细节，这些细节无不体现着八千代对于彩叶的偏爱、或是为二人创造机会的急切。</li>\n</ul>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-040.webp\" alt=\"辉夜姬-两束电光\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>屏幕右侧的七彩光为初来乍到的辉夜，而左侧急得冒汗的电光便是……？</figcaption>\n  </figure>\n<ul class=\"wiki-source-list\">\n<li><strong>别跑错了</strong>：片子一开始，辉夜抵达地球时的竹笋飞船化为七彩光芒，沿着电线杆一路乱撞；而下一幕的屏幕中出现了另一道金色电光，这道电光甚至急得冒汗，主动将七彩光引向了彩叶居所前的电线杆。由于此时的八千代已经与人类互联网充分融合，完全有理由相信这是她在引导辉夜<del>找妈妈</del>。（或是命中注定哦！）</li>\n<li>#此处插入另一个小猜想，在动漫中，辉夜降生的电线杆上有“743A”这几个数字，这个编号并不符合日本的电线杆编号，并且从远处看这串字符所处位置是模糊的，但可以通过格式看出是正常的编号，但是镜头拉近之后就会变成不正常的“743A”，除了动漫以外，在MV【ray】中也可以看到这个电线杆上有一张承载着“743A”的纸。根据了解，“743A”是稳压二极管中的一员，当电压超过7.3V后，会迅速导通，并将多余电压转换成电流释放。而辉夜赶路时的表现形式是一股庞大的“电流”在电线之间流通，因此可以将这些外溢的电流视为是被743A释放出来的，也因此辉夜才会是小孩模样？（也许可以问问制作组这个地方是什么……）</li>\n</ul>\n<ul class=\"wiki-source-list\">\n<li><strong>音效库限时免费</strong>：紧接上条，在彩叶犹豫要不要把小婴儿抱走的节骨眼，周围突然传来包括但不限于醉汉乱嚷、流浪狗叫、汽车刹车和玻璃碎裂声。虽然彩叶此时所住公寓的环境确实不怎么样，但这些音效在这个节骨眼扎堆出现，着实有些刻意了（治安突然变差了啊！）。</li>\n<li>#动漫中醉汉走过去之后，电线杆旁边突然多了一根被砍伐的竹子（不像BUG）！</li>\n</ul>\n<ul class=\"wiki-source-list\">\n<li><strong>年龄差距大点怎么了</strong>：在小辉夜与彩叶首次交流时，彩叶为缓解紧张情绪，下意识地望向屏幕中的八千代，此时的八千代正好在做有关<strong>忘年恋</strong>主题的杂谈直播。</li>\n</ul>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-027.webp\" alt=\"辉夜姬-喜欢年龄差距大点有什么问题\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>你看她笑得多开心啊（迫真）</figcaption>\n  </figure>\n<ul class=\"wiki-source-list\">\n<li><strong>意绵绵静日玉生香</strong>：除了“想要让彩叶与辉夜一起度过愉快的经历”，剧组还为八千代塞了另外一些小巧思，这些小巧思犹如J.D. 塞林格笔下那种<em>“爱是触而未触，似有若无”</em>的描述，将八千代内心的纠结与卑微体现得淋漓尽致。</li>\n</ul>\n<ul class=\"wiki-source-list\">\n<li><strong>不想被察觉到的泪</strong>：在联动演唱会期间，辉夜与八千代都需要进行较大幅度的唱跳动作，因此在演唱完第二首曲目《<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Ex-Otogibanashi\" target=\"_blank\" rel=\"noopener noreferrer\">Ex-Otogibanashi</a>》时，两人的脸上都已经满是液珠；但值得注意的是，辉夜的脸上是因为运动而正常地流出的汗，而无法流汗的虚拟歌姬八千代，则是在眼角悄悄地流下了泪水。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:300px\">\n    <img src=\"/assets/images/wiki/content/source-041.webp\" alt=\"辉夜姬-一般人流的是汗\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>辉夜此时是正常地流汗的</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:300px\">\n    <img src=\"/assets/images/wiki/content/source-022.webp\" alt=\"辉夜姬-孤寡老人偷偷抹泪\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>而八千代却在默默流泪</figcaption>\n  </figure>\n</div>\n<ul class=\"wiki-source-list\">\n<li><strong>不想做掩饰的歌词</strong>：受制于篇幅，动画中的歌曲基本都只演唱半首，还是以犹如八千代内心独白的《Ex-Otogibanashi》举例，这首歌前半段的歌词已经具有令人心痛的只言片语<em>（“此刻与你共睹的这片景色/究竟在脑海回放了几亿遍呢”）</em>，而未收录入剧中的第二段歌词，则将八千代在漫长岁月里的孤寂、煎熬和绝望平铺直叙了出来<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\"><em>（“日复一日 月复一月 年复一年/尽是无趣 寂寞 与悲伤的每天/怎么号啕痛哭 放声嘶吼 迁怒发泄/甚至连这些最后都腻倦了 只剩一了百了的想法”）</em></span>。</li>\n</ul>\n<ul class=\"wiki-source-list\">\n<li><strong>记忆里的旧居</strong>：辉夜对彩叶一见钟情时，她的身体大概处于十岁的状态，这时候的她所看到的房间里的一切都显得更大，而这时候彩叶的漱口杯里也只有一支牙刷。在辉夜开始直播后，她与彩叶的个人用品逐渐混淆，漱口杯里也多出了属于她的那一支牙刷。而在八千代于月读空间里复原的旧居中，或许是由于她仍然对彩叶心怀顾虑，担心对方不敢接受自己；又或许是她只是单纯地想还原最初的景象，这个记忆中的房间的尺寸被等比例放大，而漱口杯里也只有一支牙刷。当然，这一间屋子的细节还不止如此——例如小圆桌上堆满的可乐和薯片，就是两人在直播涨粉时一同享用过的食品<del>，只是八千代力有未逮，没能实装味觉，这些记忆里的食品终究是与松饼一样，吃了个寂寞</del>。</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-042.webp\" alt=\"辉夜姬-一根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>初来乍到，一根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-039.webp\" alt=\"辉夜姬-两根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>不当外人，两根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:225px\">\n    <img src=\"/assets/images/wiki/content/source-032.webp\" alt=\"辉夜姬-又变回了一根牙刷\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>如履薄冰，又变回了一根牙刷</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-009.webp\" alt=\"辉夜姬-爱吃的零食，虽然没味道\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>零食满桌，然而食之无味</figcaption>\n  </figure>\n</div>\n<ul class=\"wiki-source-list\">\n<li><strong>同一件T恤</strong>：彩叶的黑色旧T恤同样是贯穿全剧的重要意象——同一件衣服，穿在十岁外观的小辉夜身上犹如童装，穿在十四岁外观的辉夜身上显得很呆，但在八千代的身上，就显现出了莫名其妙的……呃……</li>\n</ul>\n<div class=\"wiki-source-media-grid wiki-source-media-center\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:180px\">\n    <img src=\"/assets/images/wiki/content/source-031.webp\" alt=\"辉夜姬-同一件T恤0\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>宝宝，可爱</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:320px\">\n    <img src=\"/assets/images/wiki/content/source-030.webp\" alt=\"辉夜姬-同一件T恤1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>呆呆的，也很可爱</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-029.webp\" alt=\"辉夜姬-同一件T恤2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>试图诱惑彩叶的吃人怪兽……</figcaption>\n  </figure>\n</div>\n<ul class=\"wiki-source-list\">\n<li><strong>是寻求母亲，还是寻求……？</strong>：不同于第三人称视角、情感表达较为含蓄的动画，官方小说则以彩叶为第一人称视角，以她的口吻加入了大量的内心戏。在这些内心戏中，彩叶不仅若干次地强调自己对于全年龄段（婴儿、幼儿、十岁孩童、十四岁孩童等）的辉夜的喜爱，甚至还在最后从八千代的歌声中，感受到了自己曾经渴望从生母身上获取的某些情感<del>，就差把<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/oo%E6%98%AF%E8%83%BD%E6%88%90%E4%B8%BA%E6%88%91%E6%AF%8D%E4%BA%B2%E7%9A%84%E5%A5%B3%E6%80%A7\" target=\"_blank\" rel=\"noopener noreferrer\">八千代是可以成为自己母亲的女人</a>给写在那儿了</del>。结合彩叶抚养辉夜的经历，这段经历也与官方MV「ray」当中的、小彩叶哭着从橱柜中扑向有着八千代眉目轮廓的辉夜的一幕相合，明确地表达了这对共轭母女(?)的彼此珍重与眷恋。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">我的女儿是看着我长大的妈妈，我的妈妈是我亲手养大的女儿，而且她们还是我的老婆，哇太爽了</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>真想再和你一起吃松饼啊</strong>：一般来说，标准的松饼会以面粉和鸡蛋为主要原料，通过泡打粉等实现松软口感，并加入糖等风味料进行调味；而彩叶为辉夜准备的穷鬼版“松饼”仅由面粉与水构成，这种寡淡的成品一般有另一个更贴切的名字——煎饼。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">然而，就是这么一款辉夜刚一进嘴就表示难吃到爆的粗劣食物，却在八千年的岁月里令她魂牵梦萦了无数次。</span></p>\n<ul class=\"wiki-source-list\">\n<li><strong>是你的事，我便记得</strong>：辉夜几乎记得彩叶对她说过的每一句话，譬如彩叶在对阵“黑玛瑙”3V3比赛期间说出的“要是你搞砸了，我就不管你了”，这句语气轻松的调侃后来成为了辉夜/八千代心中最深刻的梦魇之一。</li>\n</ul>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-051.webp\" alt=\"辉夜姬-网络喷子老八（不是）\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>“弥生时代以前的饭纯纯一坨”<br>“你丫不会自己查吗”</figcaption>\n  </figure>\n<details class=\"wiki-source-hide\"><summary><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">搞砸了</span></summary><div><div class=\"wiki-source-media-grid\">\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:350px\">\n    <img src=\"/assets/images/wiki/content/source-023.webp\" alt=\"辉夜姬-搞砸了1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>再也不管你了</figcaption>\n  </figure> <figure class=\"wiki-source-media-slot wiki-source-media-resolved\" style=\"--source-media-width:340px\">\n    <img src=\"/assets/images/wiki/content/source-024.webp\" alt=\"辉夜姬-搞砸了2\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>求求你，不要……</figcaption>\n  </figure>\n</div></div></details>\n<ul class=\"wiki-source-list\">\n<li><strong>网络黑手八千代</strong>：在网络尚不发达的时代，八千代就已经在网上冲浪了，而那时候的她得要比动画及小说中的这个温和可爱的少女直球许多，一言不合就开始对线<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">正常人谁凌晨三点还在水贴啊</span>。<del>由于暴力老八的早年经历，观众们完全可以合理推断，今天的八千代仍然会对自己看不顺眼、或是伤害彩叶的网络乱象重拳出击。</del></li>\n</ul>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:月见姓</span></p>\n<p><a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Category%3A%E6%97%A9%E8%A7%81%E6%B2%99%E7%BB%87%E9%85%8D%E9%9F%B3%E8%A7%92%E8%89%B2\" target=\"_blank\" rel=\"noopener noreferrer\">Category:早见沙织配音角色</a></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"akira","title":"帝アキラ","original":"Mikado Akira","headline":"把竞技对局变成大型表演的 Black onyX 领队。","summary":"职业游戏主播团队 Black onyX 的领队。公开形象张扬自信，擅长把竞技对局变成观众参与的华丽表演。","aliases":["帝アキラ","Mikado Akira"],"tags":["Black onyX","职业玩家"],"facts":[["身份","职业玩家／主播"],["所属","Black onyX"],["擅长","KASSEN、现场调度"],["声优","入野自由"]],"sections":[["人物简介",["帝アキラ是 Black onyX 的领队，公开形象张扬、擅长制造话题，也懂得如何让一场比赛成为观众愿意参与的直播事件。"]],["剧情作用",["他向辉夜与彩叶发起 KASSEN 合作赛／挑战，使八千代杯从单纯涨粉竞赛转入正面对决。"]],["团队关系",["雷与乃依是其固定队友。三人的风格共同构成 Black onyX 的完整舞台形象。"]]],"spoiler":["帝アキラ与彩叶的现实关系属于剧情揭示。本页只在剧透区说明：他实际一直关注彩叶的处境，挑战也包含主动为她们创造曝光机会的用意。"],"relatedCharacters":["iroha","rai","noi"],"relatedTerms":["black-onyx","kassen","yachiyo-cup"],"image":"/assets/images/wiki/entries/characters/akira-tsukuyomi.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"},"imageAlt":"酒寄朝日月夜见形象清晰设定图","imageVariants":[{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/akira-tsukuyomi.webp","imageAlt":"酒寄朝日月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"}}],"imageTarget":"assets/images/wiki/entries/characters/akira-tsukuyomi.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"akira","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E5%B8%9D%E6%98%8E","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科作品条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"character","slug":"rai","label":"驹泽雷"},{"kind":"character","slug":"noi","label":"驹泽乃依"},{"kind":"term","slug":"black-onyx","label":"Black onyX"},{"kind":"term","slug":"kassen","label":"KASSEN"},{"kind":"term","slug":"yachiyo-cup","label":"八千代杯"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"酒寄朝日","group":false},{"label":"译名","valueHtml":"帝明","group":false},{"label":"别号","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">帝哥</span>","group":false},{"label":"发色","valueHtml":"红色","group":false},{"label":"瞳色","valueHtml":"金色","group":false},{"label":"年龄","valueHtml":"23","group":false},{"label":"声优","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E5%85%A5%E9%87%8E%E8%87%AA%E7%94%B1\" target=\"_blank\" rel=\"noopener noreferrer\">入野自由</a><span class=\"wiki-source-category\">分类:入野自由配音角色</span>","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">剑眉、耳环、双角、高飞车、高傲、狂气、热血、自负、同性恋、黑幕</span><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">现实：<span class=\"wiki-source-traits\">哥哥、眼镜、可靠、温柔、早熟、耳环、同性恋</span></span>","group":false},{"label":"出身地区","valueHtml":"京都？","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"职业游戏主播","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"队友：<a class=\"wiki-source-link\" href=\"/wiki/characters/noi\">驹泽乃依</a><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，但是不止队友</span>、<a class=\"wiki-source-link\" href=\"/wiki/characters/rai\">驹泽雷</a><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">妹妹：<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a></span>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>哟，我的小兔子们，你们的帝大人驾到了！</strong></big></blockquote>\n<p><strong>帝明</strong>（<strong>帝 アキラ</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>超人气职业电竞团队“黑玛瑙（Black onyX）”的核心人物，服务精神旺盛，以“本大爷”式的狂放不羁姿态出现在公众面前。</p>\n<p>作为拥有近2,000万粉丝的超级大物，“黑玛瑙”在虚拟空间「月夜见」内有着巨大的影响力，不论走到哪儿都会伴随粉丝们的热切呼唤，其出场退场也是极有派头。</p>\n<p>虽然看上去是轻浮且惹人注目的家伙，但他实际上也有着冷静沉着的另一面；这是因为……</p>\n<details class=\"wiki-source-hide\"><summary>……呀，可爱的小兔子们，就这么想深入地了解帝大人吗？</summary><div><p>帝明的真实身份是酒寄彩叶的兄长“酒寄朝日（<strong>酒寄 朝日</strong>）”，原本是个热爱足球、调皮外向的少年，但在父亲去世后便变得安静且温和，爱好也变成了电子游戏。</p>\n<p>在获得成为职业玩家的机会后，朝日独自一人前往东京，也由此与彩叶之间产生了隔阂。最终，兄妹二人解除误会，重归于好，继续以相亲相爱的家人姿态相互扶持。</p></div></details>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<details class=\"wiki-source-hide\"><summary>喂喂，一上来就打听本大爷的家庭情况吗？也太猴急了点儿罢！</summary><div><p>酒寄朝日出生在一个情况较为特殊的家庭中，其母亲酒寄红叶曾被亲生父母抛弃，父亲酒寄朝久则是被领养的孤儿。</p>\n<p>在他六岁时，父母为家中增添了一个新成员，这便是朝日的妹妹<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>。和谐友爱的家庭环境让朝日像许多男孩子那样无忧无虑地成长——他喜欢足球，喜欢户外，也喜欢捉弄稚嫩的妹妹；当然，捉弄彩叶并不是出于恶意，而是这个调皮的哥哥发自内心地喜爱妹妹的表现。</p>\n<p>幸福的生活是短暂的，在朝日十二岁的时候，父亲朝久忽然逝世，抚养子女的重担落在了母亲红叶一人身上。母亲红叶早年曾经有过极为艰苦的经历，因此她完全有能力支撑起这个家；但父亲的离世仍然对兄妹二人的性格产生了重大影响，朝日开始由傲慢与鲁莽变得耐心且沉稳，会主动挡在与妈妈爆发争吵的妹妹彩叶身前。</p>\n<p>渐渐地，朝久喜欢上了电子游戏，成为了职业玩家，随后独自一人前往东京发展，而这被年幼的妹妹彩叶误以为是抛弃和背叛的表现，兄妹之间就此变得疏离。事实上，妹妹彩叶知道朝日使用“帝明”的ID，所以始终默默关注着兄长的直播活动；而朝日也一直挂念着妹妹彩叶，虽然事业繁忙，但他也通过爷爷奶奶大概知晓妹妹彩叶的境况。</p>\n<p>在故事正式开始前，朝久已经与<a class=\"wiki-source-link\" href=\"/wiki/characters/noi\">驹泽乃依</a>和<a class=\"wiki-source-link\" href=\"/wiki/characters/rai\">驹泽雷</a>组成了职业电竞三人组“黑玛瑙”，坐拥1,900万以上的粉丝，是当之无愧的直播大物……以及暴发户。</p></div></details>\n<p>作为数届《合战》联赛的冠军，职业电竞队伍“黑玛瑙”是虚拟空间「月夜见」（下文称“月读空间”）最炙手可热的组合之一，而队长帝明更是这支组合的灵魂人物。其狂气的外形与不羁的谈吐吸引眼球无数，每次登场都能引来迷弟迷妹一众欢呼。</p>\n<p>面对“月读空间”管理者兼主播<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a>有关举办“八千代杯”的重磅消息，“黑玛瑙”不请自来，并对八千代举办首次联动演唱会的机遇表示势在必得；然而，<a class=\"wiki-source-link\" href=\"/wiki/characters/kaguya\">一位名不见经传的小姑娘</a>的放声大喝突然打断了正出风头的帝明，虽说有些煞风景，但“黑玛瑙”也并不在意。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-021.webp\" alt=\"辉夜姬-床头上摆的什么？\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>你说你关注就关注，你床头那个辉夜大娃娃回头准备怎么跟人解释呢？</figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-026.webp\" alt=\"辉夜姬-大哥也有不能输的理由！\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption><del>帝哥也有不能输的理由！</del><br><del>BGM：<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E5%A4%96%E6%8C%82\" target=\"_blank\" rel=\"noopener noreferrer\">背背背背起了行囊</a></del></figcaption>\n  </figure>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-020.webp\" alt=\"辉夜姬-当她离去的时候，向她递出手的人，一个是亲人，而另一个……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>当彩叶离去的时候，向她递出手的两个人，一个是哥哥，而另一个……</figcaption>\n  </figure>\n<p>在接下来的一个月里，这个名叫辉夜的小姑娘与她的伙伴所组成的“辉夜x彩P”组合迅速崛起，以堪称雷霆般的速度从零冲向百万粉丝；话虽如此，“黑玛瑙”的优势仍然不可撼动，但帝明却从辉夜及其伙伴的身上感受到了某种可能性，便欣然向辉夜发出挑战书，要求与其进行《合战》的3V3对决；帝明甚至还在挑战书末尾加上了“要是我赢了，你就得嫁我为妻”的挑衅，俨然是不将对手放在眼里。</p>\n<p>事实上，早在辉夜与彩P直播的前期，帝明就已经越过耀眼夺目的辉夜，注意到了其背后的那个身影——别人认不出来，但彩P的真实身份却瞒不过他这个兄长的眼睛；他在那时就已经暗下决心，要想办法拉妹妹和她的好朋友一把。</p>\n<p>比赛当日，被两人组拉来凑人头的美食探店主播<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">MAMIMAMI</a>因近距离目睹偶像帝明，情绪过于激动而无法继续比赛；此时八千代突然乱入，作为替补队员加入了彩叶与辉夜的队伍<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然而此时芦花就在看台上，八千代的小心思昭然若揭</span>。</p>\n<p>“黑玛瑙”毕竟是正儿八经的职业选手，为弥补实力差距，八千代的面板属性有所上调，但在迎击三人时仍然颇为吃力；在与“黑玛瑙”进行鏖战期间，彩叶被迫脱下自己用于掩盖身份的狐狸皮套，公开了与帝明的兄妹关系；兄妹两人最终摒弃前嫌、重归于好，但对游戏理解更加深刻的“黑玛瑙”还是精彩地赢下了比赛。</p>\n<p>虽说“黑玛瑙”赢下了《合战》3V3对决的胜利，但帝明却并不打算冒犯妹妹和她的好朋友；相反，他大大方方地目睹彩叶和辉夜赢得“八千代杯”的胜利，还反过头来做了人情、为妹妹担保，帮助姐妹俩搬进了环境更好的顶层公寓套间。“黑玛瑙”没有入场观看姐妹俩与八千代的联动演唱会，却在场外默默注视了全程。</p>\n<p>不久，辉夜宣布隐退和即将举办毕业演唱会的消息传来，帝明与“黑玛瑙”也在随后从彩叶口中得知了辉夜的真实身份——辉夜确实是不甘无聊、逃离月球的月人公主，此前的插曲正是月人发出的引渡讯号，而她即将在下个月圆之夜离开；面对妹妹的恳求，帝明当仁不让，与其他人计划在辉夜的毕业演唱会上迎击月人。</p>\n<p>毕业演唱会的日子很快到来。伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；雷与乃依相继被击败，帝明也因检测到作弊程序而被强制踢出对局；彩叶总算在众人的支持下抵达了辉夜的舞台前，然而，她仍然无法阻止月人带走辉夜。最终，辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝；而望着强打精神、向大家表示感谢的彩叶，帝明自然而然地向着登出的彩叶伸出手去，却不知道该如何安慰。</p>\n<p>虽说妹妹因为这件事而变得消沉不已，但令帝明感到欣慰的是，彩叶没过几天便重新振作，走出阴影，决定重启自己的人生，而与辉夜度过的经历则将成为一场美好的梦，激励她翻开新的篇章。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>不对吧，本大爷的妹妹才不会是那么柔弱不堪的女孩子！让他们见识一下罢，彩叶！</summary><div><p>没错！故事到此并没有结束，因为我们的彩叶同学不甘于这种唐突的结局，势必要开辟出一个真正的Happy End！</p>\n<p>于是，帝明忽然得知自己的好妹妹再次推辞一切社交、再次闷头作曲，先是出了趟门，紧接着就指天发誓，决定弃文从理了！</p>\n<p>再然后，彩叶就仿佛开了挂一般，在科学领域经历了一次又一次堪称天翻地覆的飞跃；时间眨眼来到十年后，功成名就的酒寄彩叶博士突然邀请自己哥仨造访研究所，然后一张口就是借钱！</p>\n<p>而最后，大家更是惊讶地发现，原来彩叶在这期间的一切努力，都是为了让辉夜以合成人的躯体再度复活！</p>\n<p>虽说这种超展开哪怕是在他这个当哥哥的眼里，都实在有点儿太夸张了……话虽如此，这的确可以称得上是一个皆大欢喜、可喜可贺的Happy End罢！</p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong><del>怎么你们一家子都是同啊？</del></strong>：在小说的新·终章内，帝明与乃依已经是同居关系；而在动画的最后，帝明人间体的左手无名指上也清晰地出现了戒指。其含义不言而喻。<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">这或许就是雷一有空就到处出国旅行的原因。</span></li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">可怜的红叶女士永远也抱不上孙子或外孙子了，但大概可以叫彩叶给她搓俩合成人娃娃抱（大雾）。</span></p>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:酒寄姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"rai","title":"驹泽雷","original":"駒沢雷","headline":"Black onyX 中冷静寡言、兼具竞技与演唱能力的成员。","summary":"Black onyX 成员，驹泽乃依的哥哥。话不多、性格冷静，同时拥有出色的演唱能力。","aliases":["駒沢雷"],"tags":["Black onyX","主播"],"facts":[["身份","职业玩家／主播"],["所属","Black onyX"],["关系","驹泽乃依的哥哥"],["声优","内田雄马"]],"sections":[["人物简介",["驹泽雷话不多，常以冷静表现平衡团队的张扬气氛。除竞技实力外，他也具备出色的演唱能力。"]],["团队位置",["在 Black onyX 的三人配置中，雷负责提供稳定感，并与乃依形成鲜明的兄弟组合。"]]],"spoiler":[],"relatedCharacters":["akira","noi"],"relatedTerms":["black-onyx","kassen"],"image":"/assets/images/wiki/entries/characters/rai-tsukuyomi.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"},"imageAlt":"驹泽雷月夜见形象清晰设定图","imageVariants":[{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/rai-tsukuyomi.webp","imageAlt":"驹泽雷月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"}}],"imageTarget":"assets/images/wiki/entries/characters/rai-tsukuyomi.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"rai","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E9%A9%B9%E6%B3%BD%E9%9B%B7","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科作品条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"akira","label":"帝アキラ"},{"kind":"character","slug":"noi","label":"驹泽乃依"},{"kind":"term","slug":"black-onyx","label":"Black onyX"},{"kind":"term","slug":"kassen","label":"KASSEN"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"駒沢雷","group":false},{"label":"译名","valueHtml":"驹泽雷","group":false},{"label":"别号","valueHtml":"","group":false},{"label":"发色","valueHtml":"灰色","group":false},{"label":"瞳色","valueHtml":"金色","group":false},{"label":"年龄","valueHtml":"19","group":false},{"label":"声优","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E5%86%85%E7%94%B0%E9%9B%84%E9%A9%AC\" target=\"_blank\" rel=\"noopener noreferrer\">内田雄马</a><span class=\"wiki-source-category\">分类:内田雄马配音角色</span>","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">兽耳、独角、短发、耳环、僧侣、兜帽、哥哥、无口、高飞车、高傲</span><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">现实：<span class=\"wiki-source-traits\">短发、耳环、可靠、哥哥</span></span>","group":false},{"label":"出身地区","valueHtml":"","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"职业游戏主播","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"队友：<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a><br>队友及弟弟：<a class=\"wiki-source-link\" href=\"/wiki/characters/noi\">驹泽乃依</a>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>好了，又到了狂欢的时间。</strong></big></blockquote>\n<p><strong>驹泽雷</strong>（<strong>駒沢雷</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>超人气职业电竞团队“黑玛瑙（Black onyX）”的成员之一，自信满满而略带傲慢的坦克兼肉盾，意外地擅长唱歌。</p>\n<p>作为拥有近2,000万粉丝的超级大物，“黑玛瑙”在虚拟空间「月夜见」内有着巨大的影响力，不论走到哪儿都会伴随粉丝们的热切呼唤，其出场退场也是极有派头。</p>\n<p>沉着冷静、不苟言笑，经常会提醒口无遮拦的乃依。由于几乎不主动说话，乃依为他专门准备了《雷的专用台词集（随时更新）》，要求他熟记内容，该到他说话的时候照着背就行。</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>故事正式开始前，驹泽雷已经与<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a>和<a class=\"wiki-source-link\" href=\"/wiki/characters/noi\">驹泽乃依</a>组成职业电竞队伍“黑玛瑙”，很出名。</p>\n<p>作为数届《合战》联赛冠军，“黑玛瑙”是虚拟空间「月夜见」（下文称“月读空间”）的当红组合之一。队长帝明狂气高傲，弟弟乃依古灵精怪，雷则是队伍的后盾。</p>\n<p>面对<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a>有关举办“八千代杯”的消息，“黑玛瑙”对此势在必得；<a class=\"wiki-source-link\" href=\"/wiki/characters/kaguya\">一位小姑娘</a>打断了帝明的出风头，但“黑玛瑙”并不在意。</p>\n<p>虽说“黑玛瑙”的优势不可撼动，但帝明却主动向辉夜发出3V3挑战书，还在挑战书末尾进行挑衅，这很不礼貌，也不明智。</p>\n<p>比赛当日，主播<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">MAMIMAMI</a>无法继续比赛；八千代乱入作为替补。</p>\n<p>“黑玛瑙”很强，为弥补实力差距，八千代的属性有所上调，但这影响不了比赛结果。最终，“黑玛瑙”赢下对决，而彩叶和辉夜赢得了“八千代杯”。“黑玛瑙”没有入场观看联动演唱会，只在场外稍驻。</p>\n<p>不久，辉夜宣布隐退，即将举办毕业演唱会，“黑玛瑙”也从彩叶口中得知了辉夜的真实身份——辉夜确实是月人的公主，她将在下个满月离开；“黑玛瑙”答应彩叶，共同在毕业演唱会上迎击月人。</p>\n<p>毕业演唱会很快到来。伴随着辉夜的歌声，我方与月人爆发战斗。其余队友很快落败，我方即便使用作弊手段也仍然不敌；彩叶成功抵达舞台前，仍然无法阻止月人带走辉夜。最终，辉夜离去；而大家不知该如何安慰彩叶，只能目送她登出。</p>\n<p>令人欣慰的是，彩叶没过几天便重新振作，走出阴影，而此前的经历将成为一场美梦。真是皆大欢喜，可喜可贺。</p>\n<details class=\"wiki-source-hide\"><summary>乃依的台词集里没写后边这段内容，回头会提醒他补上，这里就简单介绍一下。</summary><div><p>故事到此并未结束，因为彩叶不甘于这种结局。</p>\n<p>不久，彩叶先是推辞社交、随后出了趟门，接着指天发誓，决定弃文从理。</p>\n<p>再然后，彩叶在科技领域不断取得突破；十年后，酒寄彩叶博士邀请“黑玛瑙”造访研究所，提出了赞助的请求。</p>\n<p>最后，彩叶的努力得到了回报，辉夜以合成人的躯体复活了。</p>\n<p>虽然很不可思议，但这的确是一个皆大欢喜、可喜可贺的Happy End。</p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong><del>呃，这条设定似乎没用上啊</del></strong>：角色设定集里强调，说雷的唱歌水平很不错，但在“黑玛瑙”的登场曲《<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/OnyXXX\" target=\"_blank\" rel=\"noopener noreferrer\">OnyXXX</a>》里，声优内田雄马的音色都快低成贝斯了……也没体现出唱歌水平来。</li>\n</ul>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:驹泽姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"noi","title":"驹泽乃依","original":"駒沢乃依","headline":"认真回应粉丝、偏爱可爱装扮的 Black onyX 成员。","summary":"Black onyX 成员，雷的弟弟。使用男性虚拟形象，偏爱可爱服装，认真营业时很会回应粉丝。","aliases":["駒沢乃依"],"tags":["Black onyX","主播"],"facts":[["身份","职业玩家／主播"],["所属","Black onyX"],["关系","驹泽雷的弟弟"],["声优","松冈祯丞"]],"sections":[["人物简介",["驹泽乃依使用男性虚拟形象，却偏爱可爱的服装与营业方式。认真活动时，他很擅长回应粉丝。"]],["团队位置",["乃依为 Black onyX 增加轻快和亲近感，与雷的沉稳、アキラ的张扬形成互补。"]]],"spoiler":[],"relatedCharacters":["akira","rai"],"relatedTerms":["black-onyx","kassen"],"image":"/assets/images/wiki/entries/characters/noi-tsukuyomi.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"},"imageAlt":"驹泽乃依月夜见形象清晰设定图","imageVariants":[{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/noi-tsukuyomi.webp","imageAlt":"驹泽乃依月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图"}}],"imageTarget":"assets/images/wiki/entries/characters/noi-tsukuyomi.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"noi","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E9%A9%B9%E6%B3%BD%E4%B9%83%E4%BE%9D","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科作品条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"akira","label":"帝アキラ"},{"kind":"character","slug":"rai","label":"驹泽雷"},{"kind":"term","slug":"black-onyx","label":"Black onyX"},{"kind":"term","slug":"kassen","label":"KASSEN"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"駒沢乃依","group":false},{"label":"译名","valueHtml":"驹泽乃依","group":false},{"label":"别号","valueHtml":"<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">我嘞个烧冈</span>、<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">哥夫</span>、<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">男嫂子</span>","group":false},{"label":"发色","valueHtml":"内层挑染（黑色-&gt;粉色）","group":false},{"label":"瞳色","valueHtml":"粉色","group":false},{"label":"年龄","valueHtml":"16","group":false},{"label":"生日","valueHtml":"2月23日<span class=\"wiki-source-category\">分类:2月23日</span>","group":false},{"label":"星座","valueHtml":"","group":false},{"label":"声优","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%9D%BE%E5%86%88%E7%A5%AF%E4%B8%9E\" target=\"_blank\" rel=\"noopener noreferrer\">松冈祯丞</a><span class=\"wiki-source-category\">分类:松冈祯丞配音角色</span>","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">伪娘、兽耳、双角、双马尾、广袖、超短裙、迷你裙、白色短袜、地雷系、日式小学生书包、怕麻烦、慵懒、垂眼、同性恋、黑幕、嫂子，黑幕</span><br><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">现实：<span class=\"wiki-source-traits\">耳环、怕麻烦、同性恋、嫂子</span></span>","group":false},{"label":"出身地区","valueHtml":"","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"职业游戏主播","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"队友：<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，但是不止队友</span><br>兄长及队友：<a class=\"wiki-source-link\" href=\"/wiki/characters/rai\">驹泽雷</a>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<blockquote class=\"wiki-source-quote\"><big><strong>有我的风格，我们肯定稳赢，对吧？</strong></big></blockquote>\n<p><strong>驹泽乃依</strong>（<strong>駒沢乃依</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>超人气职业电竞团队“黑玛瑙（Black onyX）”的成员之一，性格无常，以身着可爱女装的姿态出现在公众面前。</p>\n<p>作为拥有近2,000万粉丝的超级大物，“黑玛瑙”在虚拟空间「月夜见」内有着巨大的影响力，不论走到哪儿都会伴随粉丝们的热切呼唤，其出场退场也是极有派头。</p>\n<p>悠哉游哉、很怕麻烦，喜欢在口头上挑衅帝，但要是有求于他、或是有了动力的话，他倒是也会全力以赴。</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>在故事正式开始前，驹泽乃依已经与<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a>和<a class=\"wiki-source-link\" href=\"/wiki/characters/rai\">驹泽雷</a>组成了职业电竞三人组“黑玛瑙”，坐拥1,900万以上的粉丝，是当之无愧的直播大物。</p>\n<p>作为数届《合战》联赛的冠军，职业电竞队伍“黑玛瑙”是虚拟空间「月夜见」（下文称“月读空间”）最炙手可热的组合之一。虽说队长帝明的狂气与高傲吸引着无数人，但乃依才是这支队伍的关键策划——“黑玛瑙”由单纯的电竞队伍转向偶像团体，相关活动都是由这位比<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>还要年幼一岁的小弟弟操办的。</p>\n<p>面对“月读空间”管理者兼主播<a class=\"wiki-source-link\" href=\"/wiki/characters/yachiyo\">月见八千代</a>有关举办“八千代杯”的重磅消息，“黑玛瑙”不请自来，并对八千代举办首次联动演唱会的机遇表示势在必得；然而，<a class=\"wiki-source-link\" href=\"/wiki/characters/kaguya\">一位名不见经传的小姑娘</a>的放声大喝突然打断了正出风头的帝明，虽说有些煞风景，但“黑玛瑙”也并不在意。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:200px\">\n    <img src=\"/assets/images/wiki/content/source-018.webp\" alt=\"辉夜姬-我勒个\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>乃依的杀必死</figcaption>\n  </figure>\n<p>在接下来的一个月里，这个名叫辉夜的小姑娘与她的伙伴所组成的“辉夜x彩P”组合迅速崛起，以堪称雷霆般的速度从零冲向百万粉丝；话虽如此，“黑玛瑙”的优势仍然不可撼动，但帝明却从辉夜及其伙伴的身上感受到了某种可能性，便欣然向辉夜发出挑战书，要求与其进行《合战》的3V3对决；帝明甚至还在挑战书末尾加上了“要是我赢了，你就得嫁我为妻”的挑衅，俨然是不将对手放在眼里。</p>\n<p>比赛当日，被两人组拉来凑人头的美食探店主播<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">MAMIMAMI</a>因近距离目睹偶像帝明，情绪过于激动而无法继续比赛；此时八千代突然乱入，作为替补队员加入了彩叶与辉夜的队伍<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，然而此时芦花就在看台上，八千代的小心思昭然若揭</span>。</p>\n<p>“黑玛瑙”毕竟是正儿八经的职业选手，为弥补实力差距，八千代的面板属性有所上调，但乃依的牵制仍然对八千代的行动造成了很大阻碍。最终，对游戏理解更加深刻的“黑玛瑙”精彩地赢下了《合战》3V3对决，而彩叶和辉夜却以微弱优势赢得了“八千代杯”的胜利。“黑玛瑙”没有入场观看姐妹俩与八千代的联动演唱会，却在场外默默注视了全程。</p>\n<p>不久，辉夜宣布隐退和即将举办毕业演唱会的消息传来，“黑玛瑙”也从彩叶口中得知了辉夜的真实身份——辉夜确实是不甘无聊、逃离月球的月人公主，此前的插曲正是月人发出的引渡讯号，而她即将在下个月圆之夜离开；面对彩叶的恳求，乃依一如既往地嫌麻烦，但还是答应与其他人在辉夜的毕业演唱会上迎击月人。</p>\n<p>毕业演唱会的日子很快到来。伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">——由前后文推断，“黑玛瑙”的外挂很有可能是由乃依负责开发的</span>；雷与乃依相继被击败，帝明也因检测到作弊程序而被强制踢出对局；彩叶总算在众人的支持下抵达了辉夜的舞台前，然而，她仍然无法阻止月人带走辉夜。最终，辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝；而望着强打精神、向大家表示感谢的彩叶，大家都不知道该如何安慰她，只能注视她默默登出游戏。</p>\n<p>虽说队长的好妹妹因为这件事而变得消沉不已，但令大家意想不到的是，彩叶没过几天便重新振作，走出阴影，决定重启自己的人生，而与辉夜度过的经历则将成为一场美好的梦，激励她翻开新的篇章。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>诶——？这就结束了吗？真麻烦啊……</summary><div><p>……当然有了！故事到此并没有结束，因为我们的彩叶同学不甘于这种唐突的结局，势必要开辟出一个真正的Happy End！</p>\n<p>于是，“黑玛瑙”的诸位忽然得知，队长的好妹妹再次推辞一切社交、再次闷头作曲，先是出了趟门，紧接着就指天发誓，决定弃文从理了！</p>\n<p>再然后，这位小妹妹就仿佛开了挂一般，在科学领域经历了一次又一次堪称天翻地覆的飞跃；时间眨眼来到十年后，功成名就的酒寄彩叶博士突然邀请“黑玛瑙”造访研究所，然后一张口就是借钱！</p>\n<p>而最后，大家更是惊讶地发现，原来彩叶在这期间的一切努力，都是为了让辉夜以合成人的躯体再度复活！</p>\n<p>虽说这种超展开实在有点儿太夸张了……话虽如此，既然她答应给乃依也做一副基于月读空间虚拟外观的合成人，那这的确可以称得上是一个皆大欢喜、可喜可贺的Happy End罢！</p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong><del>怎么你们一家子都是同啊？</del></strong>：在小说的新·终章内，乃依与帝明已经是同居关系；而在动画的最后，帝明人间体的左手无名指上也清晰地出现了戒指。其含义不言而喻。<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">这或许就是雷一有空就到处出国旅行的原因。</span></li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">可怜的红叶女士永远也抱不上孙子或外孙子了，但大概可以叫彩叶给她搓俩合成人娃娃抱（大雾）。</span></p>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:驹泽姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"roka","title":"绫䌷芦花","original":"綾紬芦花","headline":"能够看穿彩叶逞强的朋友与美妆创作者。","summary":"彩叶的朋友与美妆类创作者。她能察觉彩叶的逞强，并持续关心朋友的生活状况。","aliases":["綾紬芦花"],"tags":["彩叶的朋友","美妆创作者"],"facts":[["身份","高中生／美妆创作者"],["关系","彩叶、真实的朋友"],["活动范围","现实、月读"],["声优","青山吉能"]],"sections":[["人物简介",["绫䌷芦花是彩叶在学校与现实生活中的重要朋友。她经营美妆类内容，对形象和他人状态都很敏锐。"]],["与彩叶",["芦花能察觉彩叶把疲惫藏在“什么都能处理”的外表下。辉夜出现后，她也很快发现彩叶的生活正在发生变化。"]]],"spoiler":[],"relatedCharacters":["iroha","mami","kaguya"],"relatedTerms":["tsukuyomi"],"image":"/assets/images/wiki/entries/characters/roka-reality.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"},"imageAlt":"绫䌷芦花现实形象清晰设定图","imageVariants":[{"id":"reality","label":"现实","image":"/assets/images/wiki/entries/characters/roka-reality.webp","imageAlt":"绫䌷芦花现实形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"}},{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/roka-tsukuyomi.webp","imageAlt":"绫䌷芦花月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（月夜见形象）"}}],"imageTarget":"assets/images/wiki/entries/characters/roka-reality.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"roka","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E7%BB%AB%E4%8C%B7%E8%8A%A6%E8%8A%B1","standalone":true},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科作品条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"character","slug":"mami","label":"谏山真实"},{"kind":"character","slug":"kaguya","label":"辉夜"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"綾紬芦花","group":false},{"label":"译名","valueHtml":"绫䌷芦花","group":false},{"label":"别号","valueHtml":"芦花女士","group":false},{"label":"发色","valueHtml":"褐色","group":false},{"label":"瞳色","valueHtml":"蓝","group":false},{"label":"年龄","valueHtml":"17？","group":false},{"label":"生日","valueHtml":"4月5日<span class=\"wiki-source-category\">分类:4月5日</span>","group":false},{"label":"星座","valueHtml":"","group":false},{"label":"声优","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E9%9D%92%E5%B1%B1%E5%90%89%E8%83%BD\" target=\"_blank\" rel=\"noopener noreferrer\">青山吉能</a><span class=\"wiki-source-category\">分类:青山吉能配音角色</span>","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">高中生、吊眼、眼影、耳环、美甲、中长发、黑色短袜、水手服、超短裙、温柔、认真、优等生、单恋、黑幕、百合、黑幕</span><br>月读：<span class=\"wiki-source-traits\">长发、双角、辫子、外套半脱、超短裙、热裤、长靴</span>","group":false},{"label":"出身地区","valueHtml":"","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"高中二年级学生&amp;美妆博主<br>→超人气网红&amp;品牌大使","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"闺蜜：<a class=\"wiki-source-link\" href=\"/wiki/characters/mami\">谏山真实</a><br>也是闺蜜<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">，但是持有“特别的感情”</span>：<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<p><strong>绫䌷芦花</strong>（<strong>綾紬 芦花</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>高中二年级学生，彩叶的同班同学，十分热爱美妆与时尚文化。</p>\n<p>在虚拟空间「月夜见」内，作为有着十余万粉丝的美容系网红“ROKA”而活跃，也会与彩叶和真实一起联机PVP。</p>\n<p>虽然是有着纤细性格、引人注目的美人，可在她精致迷人的外观下，却对彩叶持有“特别的感情”<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">；然而，她终究是没有勇气踏出那一步</span>。</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>芦花与真实作为彩叶的同班同学，两人共同构成了彩叶在学校乃至现实生活当中的重要依靠。相对于专研美食的真实来说，芦花在时尚领域上极有心得。</p>\n<p>两人对彩叶独自过活、负担很重的情况有所感知，因此经常在日常中创造机会，或是领着彩叶出门散心、或是找理由请她大快朵颐；尽管如此，两人对于彩叶愈发萎靡的精神状态看在眼里，她们既不知道该如何说服彩叶，也无法深度介入她的生活。</p>\n<p>随着辉夜的闪亮登场，两人为这个“小表妹”的出现先是感到意外，而后颇为惊喜——辉夜的美貌和热情能够打动每一个人，而辉夜为彩叶带来的积极影响更是显而易见；但这并非爱屋及乌，她们自然而然地喜欢上了这个顽皮可爱的女孩。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-036.webp\" alt=\"辉夜姬-你对她施了什么魔法？\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「辉夜酱，你用了什么魔法啊？虽然有点儿不甘心，但好像真的有点儿想给你们加油了。」</figcaption>\n  </figure>\n<p>作为美妆博主，芦花积极地在辉夜的身上施加着宛若仙女教母的魔法——化妆、编头发、做美甲、选购衣物，还与真实一同带领辉夜入坑《合战》。在她们的协助下，“辉夜x彩P”的粉丝数直线蹿升，而当顶流组合“黑玛瑙”向着辉夜发来挑战书时，芦花也坐在看台上静静地欣赏了比赛<span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">——她倒是想下场</span>。</p>\n<p>随着彩叶与辉夜赢下“八千代杯”，实现与八千代的梦幻联动，芦花与真实也注意到了彩叶和辉夜之间的微妙气氛；为此，二人为姐妹俩献上了助攻，还在得知辉夜的真实身份后，一口答应彩叶迎击月人、挽留辉夜的请求。</p>\n<p>毕业演唱会的日子很快到来。伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的芦花与真实光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；彩叶在哥哥等人的支持下抵达了辉夜的舞台前，却仍然无法阻止月人带走辉夜。最终，辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝；而望着强打精神、向大家表示感谢的彩叶，芦花已经递出的手最终还是滞在了半空中。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-020.webp\" alt=\"辉夜姬-当她离去的时候，向她递出手的人，一个是亲人，而另一个……\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>当彩叶离去的时候，向她递出手的两个人，一个是哥哥，而另一个……</figcaption>\n  </figure>\n<p>眼看彩叶变得消沉下来，担心好友安危的两人跑遍了彩叶可能出现的场所；姐妹三人最终在学校碰面，而彩叶也意识到了两人对她的关心与支持、意识到了自己对于二人的珍视。就这样，姐妹三人将继续以这样温馨友爱的状态，度过一天又一天的平静日常。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>要真是这样就好了……等会儿，为什么片尾的报幕突然停了！？</summary><div><p>没错！故事到此并没有结束，因为我们的彩叶同学不甘于这种唐突的结局，势必要开辟出一个真正的Happy End！</p>\n<p>于是，芦花与真实眼睁睁地看着彩叶再次推辞一切社交、再次闷头作曲，先是出了趟门，紧接着就指天发誓，决定弃文从理了！</p>\n<p>再然后，彩叶就仿佛开了挂一般，在科学领域经历了一次又一次堪称天翻地覆的飞跃；时间眨眼来到十年后，待到芦花已为超人气网红兼品牌大使、真实做了两个孩子的母亲的时候，功成名就的酒寄彩叶博士突然邀请她们造访研究所，然后一张口就是借钱！</p>\n<p>而最后，大家更是惊讶地发现，原来彩叶在这期间的一切努力，都是为了让辉夜以合成人的躯体再度复活！</p>\n<p>虽然站在朋友乃至外人的角度来看，这种超展开不论如何都有点儿太夸张了……话虽如此，这的确可以称得上是一个皆大欢喜、可喜可贺的Happy End罢！</p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong>特别的感情</strong>：虽然在动画中表现得极为隐晦，但官方设定集介绍绫䌷芦花的段落却明确指出，芦花对彩叶怀揣<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%97%A0%E6%B3%95%E4%BC%A0%E8%BE%BE%E7%9A%84%E7%88%B1%E6%81%8B\" target=\"_blank\" rel=\"noopener noreferrer\">“特别的感情”</a>。基于这一备注，重看动画及官方MV，可以注意到芦花在与真实同屏时，眼角多次带泪的细节，以及时不时流露出的令人心酸的<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%8D%E4%B9%9F%E6%8C%BA%E5%A5%BD%E5%90%97\" target=\"_blank\" rel=\"noopener noreferrer\">挺好颜</a>。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">更绝望的是，芦花女士就连年度挺好颜的资格也无法独占，因为八千代也干了。</span></p>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:绫䌷姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"mami","title":"谏山真实","original":"諌山真実","headline":"性格随和、连接日常与主播文化的美食创作者。","summary":"彩叶的朋友与美食类创作者，也是帝アキラ的粉丝。性格随和，是可靠的同行者。","aliases":["諌山真実"],"tags":["彩叶的朋友","美食创作者"],"facts":[["身份","高中生／美食创作者"],["关系","彩叶、芦花的朋友"],["喜好","帝アキラ的活动"],["声优","小原好美"]],"sections":[["人物简介",["谏山真实是彩叶的朋友与美食类创作者。她性格随和，对热门主播和月读文化保持强烈兴趣。"]],["剧情作用",["真实让彩叶的现实朋友圈与月读活动自然连接，也在多人行动中承担气氛调节者。"]]],"spoiler":[],"relatedCharacters":["iroha","roka","akira"],"relatedTerms":["tsukuyomi","kassen"],"image":"/assets/images/wiki/entries/characters/mami-reality.webp","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"},"imageAlt":"谏山真实现实形象清晰设定图","imageVariants":[{"id":"reality","label":"现实","image":"/assets/images/wiki/entries/characters/mami-reality.webp","imageAlt":"谏山真实现实形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（现实形象）"}},{"id":"tsukuyomi","label":"月夜见","image":"/assets/images/wiki/entries/characters/mami-tsukuyomi.webp","imageAlt":"谏山真实月夜见形象清晰设定图","imageLayout":{"ratio":"3 / 4","fit":"contain","position":"center bottom","mode":"subject"},"imageSource":{"title":"用户提供的清晰角色设定图（月夜见形象）"}}],"imageTarget":"assets/images/wiki/entries/characters/mami-reality.webp","imageSuggestion":"已使用用户提供的清晰透明立绘","sourceArticle":"mami","sourceSectionLinks":[{"id":"source-profile","label":"基本资料"},{"id":"source-lead","label":"条目引言"},{"id":"source-intro","label":"简介"},{"id":"source-experience","label":"经历"},{"id":"source-trivia","label":"角色相关逸事"}],"moegirl":{"url":"https://zh.moegirl.org.cn/%E8%B0%8F%E5%B1%B1%E7%9C%9F%E5%AE%9E","standalone":true},"sourceLinks":[{"label":"萌娘百科：谏山真实","url":"https://zh.moegirl.org.cn/%E8%B0%8F%E5%B1%B1%E7%9C%9F%E5%AE%9E"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"character","slug":"roka","label":"绫䌷芦花"},{"kind":"character","slug":"akira","label":"帝アキラ"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"},{"kind":"term","slug":"kassen","label":"KASSEN"}],"songs":[],"source":{"profileRows":[{"label":"基本资料","valueHtml":"","group":true},{"label":"本名","valueHtml":"諫山真実","group":false},{"label":"译名","valueHtml":"谏山真实","group":false},{"label":"别号","valueHtml":"MAMIMAMI","group":false},{"label":"发色","valueHtml":"褐色","group":false},{"label":"瞳色","valueHtml":"褐","group":false},{"label":"年龄","valueHtml":"17？","group":false},{"label":"声优","valueHtml":"小原好美","group":false},{"label":"萌点","valueHtml":"<span class=\"wiki-source-traits\">高中生、垂眼、中长发、鬓角麻花辫、泡泡袜、水手服、温柔、优等生、吃货、姐姐</span><br>月读：<span class=\"wiki-source-traits\">长发、灯笼辫、超短裙、左右袜子不同、绝对领域、木屐、吃货</span>","group":false},{"label":"出身地区","valueHtml":"","group":false},{"label":"活动范围","valueHtml":"<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E4%B8%9C%E4%BA%AC(%E5%9C%B0%E7%82%B9)\" target=\"_blank\" rel=\"noopener noreferrer\">东京</a>","group":false},{"label":"个人状态","valueHtml":"高中二年级学生&amp;美食网红博主<br>→双胞胎的妈妈","group":false},{"label":"相关人士","valueHtml":"","group":true},{"label":"相关人士","valueHtml":"闺蜜：<a class=\"wiki-source-link\" href=\"/wiki/characters/iroha\">酒寄彩叶</a>、<a class=\"wiki-source-link\" href=\"/wiki/characters/roka\">绫䌷芦花</a><br>偶像：<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a>","group":false}],"sections":[{"id":"source-lead","title":"条目引言","html":"<p><strong>谏山真实</strong>（<strong>諫山 真実</strong>）是由<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/Studio%20Colorido\" target=\"_blank\" rel=\"noopener noreferrer\">Studio Colorido</a>与<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/STUDIO%20CHROMATO\" target=\"_blank\" rel=\"noopener noreferrer\">STUDIO CHROMATO</a>制作的动画《<a class=\"wiki-source-link\" href=\"/wiki\">超时空辉夜姬！</a>》及其衍生作品的登场角色。</p>"},{"id":"source-intro","title":"简介","html":"<p>高中二年级学生，彩叶的同班同学，喜爱品尝各类美食。</p>\n<p>在虚拟空间「月夜见」内，作为有着十余万粉丝的美食探店系网红“MAMIMAMI”而活跃，也会与彩叶和芦花一起联机PVP。</p>\n<p>性格踏实，做事麻利，是个很现实的人。其软绵绵的日常状态是她被家里人宠溺着的证明，其本人对此也确有自知。</p>\n<p>是职业电竞组合“黑玛瑙”的粉丝，尤其是队长<a class=\"wiki-source-link\" href=\"/wiki/characters/akira\">帝明</a>本人的死忠粉。</p>"},{"id":"source-experience","title":"经历","html":"<div class=\"wiki-source-spoiler-warning\"><strong>剧透提醒</strong><span>以下内容包含作品完整剧情与结局。</span></div>\n<p>真实与芦花作为彩叶的同班同学，两人共同构成了彩叶在学校乃至现实生活当中的重要依靠。相对于时尚靓丽的芦花来说，真实对于<strong>吃</strong>很有心得，是个字面意义上的老吃家。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-004.webp\" alt=\"辉夜姬-颜艺1\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>要不是真实眼里的美食之魂打动了彩叶，辉夜这第一口正儿八经的松饼也吃不进嘴</figcaption>\n  </figure>\n<p>两人对彩叶独自过活、负担很重的情况有所感知，因此经常在日常中创造机会，或是领着彩叶出门散心、或是找理由请她大快朵颐；尽管如此，两人对于彩叶愈发萎靡的精神状态看在眼里，她们既不知道该如何说服彩叶，也无法深度介入她的生活。</p>\n<p>随着辉夜的闪亮登场，两人为这个“小表妹”的出现先是感到意外，而后颇为惊喜——辉夜的美貌和热情能够打动每一个人，而辉夜为彩叶带来的积极影响更是显而易见；但这并非爱屋及乌，她们自然而然地喜欢上了这个顽皮可爱的女孩。</p>\n<figure class=\"wiki-source-media-slot wiki-source-media-resolved wiki-source-media-float-right\" style=\"--source-media-width:250px\">\n    <img src=\"/assets/images/wiki/content/source-036.webp\" alt=\"辉夜姬-你对她施了什么魔法？\" loading=\"lazy\" decoding=\"async\" data-image-bloom>\n    <figcaption>「你对她施了什么魔法？」</figcaption>\n  </figure>\n<p>作为美食博主，真实为辉夜推荐着各种各样稀奇古怪的美食，譬如样式独特的珍珠粉圆拉面、爆辣的网红食品等等；甚至于辉夜每天为彩叶烹制的饭菜也大概率受到了真实的影响，由于彩叶本人对吃喝要求极低，从炖牛舌到白甘鲷，这些高级料理的灵感来自真实是情理之中的事情。</p>\n<p>在她们的协助下，“辉夜x彩P”的粉丝数直线蹿升。不久之后，顶流组合“黑玛瑙”向着辉夜发来挑战书，真实被两人硬拉上场，却在“黑玛瑙”大驾光临比赛场地之前就兴奋得不能自已；而当帝明向着真实抛出<a class=\"wiki-source-link\" href=\"https://zh.moegirl.org.cn/%E6%9D%80%E5%BF%85%E6%AD%BB\" target=\"_blank\" rel=\"noopener noreferrer\">杀必死</a>的媚眼后，追星成功的真实更是当场昏厥。</p>\n<p>无力再战的真实被迫退场，而她的缺席则由翩然而至的八千代补位；话虽如此，辉夜随手从真实身上摘下的装饰用食品却对接下来的合战3V3对局起到了至关重要的作用，也算是让真实的场外援助战果+1了。</p>\n<p>随着彩叶与辉夜赢下“八千代杯”，实现与八千代的梦幻联动，真实与芦花也注意到了彩叶和辉夜之间的微妙气氛；为此，二人为姐妹俩献上了助攻，还在得知辉夜的真实身份后，一口答应彩叶迎击月人、挽留辉夜的请求。</p>\n<p>毕业演唱会的日子很快到来。伴随着辉夜的歌声，月人方面也派出实力深不可测的队伍，与彩叶等人爆发激烈战斗。实力不济的真实与芦花光速退赛，而“黑玛瑙”则冒着被封号的风险开挂援护彩叶；彩叶在哥哥等人的支持下抵达了辉夜的舞台前，却仍然无法阻止月人带走辉夜。最终，辉夜在众目睽睽之下踏上玉盘般的月面，犹如真正的辉夜姬那样披上羽衣、渐渐飞远消逝；而望着强打精神、向大家表示感谢的彩叶，大家都不知道该如何安慰她，只能注视她默默登出游戏。</p>\n<p>眼看彩叶变得消沉下来，担心好友安危的两人跑遍了彩叶可能出现的场所；姐妹三人最终在学校碰面，而彩叶也意识到了两人对她的关心与支持、意识到了自己对于二人的珍视。就这样，姐妹三人将继续以这样温馨友爱的状态，度过一天又一天的平静日常。真是皆大欢喜，可喜可贺啊！</p>\n<details class=\"wiki-source-hide\"><summary>哇哇哇片尾是我第一喜欢的帝大人的3rd Live——诶等会儿，这不是片尾？</summary><div><p>没错！故事到此并没有结束，因为我们的彩叶同学不甘于这种唐突的结局，势必要开辟出一个真正的Happy End！</p>\n<p>于是，真实与芦花眼睁睁地看着彩叶再次推辞一切社交、再次闷头作曲，先是出了趟门，紧接着就指天发誓，决定弃文从理了！</p>\n<p>再然后，彩叶就仿佛开了挂一般，在科学领域经历了一次又一次堪称天翻地覆的飞跃；时间眨眼来到十年后，待到真实做了两个孩子的母亲、芦花已为超人气网红兼品牌大使的时候，功成名就的酒寄彩叶博士突然邀请她们造访研究所，然后一张口就是借钱！</p>\n<p>而最后，大家更是惊讶地发现，原来彩叶在这期间的一切努力，都是为了让辉夜以合成人的躯体再度复活！</p>\n<p>虽然站在朋友乃至外人的角度来看，这种超展开不论如何都有点儿太夸张了……话虽如此，这的确可以称得上是一个皆大欢喜、可喜可贺的Happy End罢！</p></div></details>"},{"id":"source-trivia","title":"角色相关逸事","html":"<ul class=\"wiki-source-list\">\n<li><strong>我们在LGBT中找到了为数不多的一般向元素（大雾）</strong>：虽说动画正片基本没有提及，但真实与其他角色不同，她不仅有着温馨和谐的家庭环境，其本人也在大学毕业后、与自高中时代便开始交往的男友结婚，早早成为一对双胞胎的妈妈。对于《超时空辉夜姬》这么一部重视描述非正常亲子关系和同性感情的作品来说，这已经是非常难得的“一般向”元素了。</li>\n</ul>\n<p><span class=\"wiki-source-blackout\" tabindex=\"0\" title=\"你知道的太多了\">没办法，谁叫彩叶爸爸走得早呢，明明是铃村夫妻档，却基本只有坂本真绫在输出。</span></p>"},{"id":"source-notes","title":"注释及外部链接","html":"<p><span class=\"wiki-source-reference-list\">注释已随正文保留。</span></p>\n<p><span class=\"wiki-source-category\">分类:超时空辉夜姬！</span><span class=\"wiki-source-category\">分类:谏山姓</span></p>"}]}},{"kind":"character","kindLabel":"角色词条","slug":"fushi","title":"FUSHI","original":"不死","headline":"跟随八千代的海兔形向导，也是漫长时间的见证者。","summary":"外形像毛茸茸海蛞蝓的月读向导，是八千代的搭档；它对辉夜和犬DOGE抱有难以解释的戒心。","aliases":["不死","FUSHI"],"tags":["月读向导","八千代搭档"],"facts":[["身份","月读向导／八千代搭档"],["外形","海兔状虚拟生物"],["活动范围","月读与现实设施"],["声优","钉宫理惠"]],"sections":[["人物简介",["FUSHI 以毛茸茸的海兔形象活动，是八千代身边最稳定的搭档。它能引导用户，也负责处理部分空间事务。"]],["谜团",["FUSHI 对辉夜和犬DOGE表现出的警惕提示它掌握更多信息，但公开资料并未解释所有机制。"]]],"spoiler":["FUSHI 与辉夜经历的漫长时间有关，也保存或见证了八千代的重要记忆。其与犬DOGE的连续关系应以作品最终呈现为准。"],"relatedCharacters":["yachiyo","doge","iroha"],"relatedTerms":["tsukuyomi"],"image":"/assets/images/wiki/entries/characters/fushi.webp","imageLayout":{"ratio":"495 / 435","fit":"cover","position":"center center","mode":"card"},"imageSource":{"title":"《超かぐや姫！ 公式ガイドブック ハッピーエンドのその先へ！》","page":30},"imageAlt":"FUSHI角色立绘","imageVariants":[],"imageTarget":"assets/images/wiki/entries/characters/fushi.webp","imageSuggestion":"已从公式书第 30 页按角色构图处理","moegirl":{"url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81#%E4%B8%BB%E8%A6%81%E8%A7%92%E8%89%B2","standalone":false},"sourceLinks":[{"label":"作品官网角色页","url":"https://www.cho-kaguyahime.com/character/"},{"label":"萌娘百科作品条目","url":"https://zh.moegirl.org.cn/%E8%B6%85%E6%97%B6%E7%A9%BA%E8%BE%89%E5%A4%9C%E5%A7%AC%EF%BC%81"}],"verifiedAt":"2026-07-18","related":[{"kind":"character","slug":"yachiyo","label":"月见八千代"},{"kind":"character","slug":"doge","label":"犬DOGE"},{"kind":"character","slug":"iroha","label":"酒寄彩叶"},{"kind":"term","slug":"tsukuyomi","label":"月读／TSUKUYOMI"}],"songs":[],"source":null},{"kind":"character","kindLabel":"角色词条","slug":"doge","title":"犬DOGE","original":"犬DOGE","headline":"陪伴辉夜、又与 FUSHI 谜团相连的月读向导。","summary":"与辉夜一同行动的月读向导。它和 FUSHI 的关系为故事增添了不少谜团，但具体机制不在本页作无来源推断。","aliases":["犬DOGE","狗狗DOGE"],"tags":["月读向导","辉夜搭档"],"facts":[["身份","月读向导／辉夜搭档"],["外形","犬形虚拟生物"],["关联","FUSHI"],["声优",